const lessons = [
{id:'getting-started',title:'How Alight Motion works',category:'Basics',filter:'basics',level:'Beginner',icon:'i-play',color:'#05faa8',desc:'Understand projects, layers, the canvas, preview and export flow.',intro:'Alight Motion projects are built from layers of visual and audio content. Each layer has its own position in time and can have properties, animation and effects.',steps:[['Create a project','Choose a canvas ratio and frame rate that fit the edit you plan to make. Start with a short practice composition.'],['Know the main areas','The canvas shows the composition, the timeline decides when layers appear, and the selected layer controls its properties.'],['Add and label layers','Import media or create text and shapes. Rename important layers so you can find them quickly.'],['Preview before exporting','Scrub from the beginning to the end and check the framing, transitions, audio and final frame.']],tip:'Keep the project simple until the motion works. Add polish after the structure is solid.',challenge:'Make a short composition with one background, one image and one text layer. Rename each layer.'},
{id:'timeline-basics',title:'Master the timeline',category:'Basics',filter:'basics',level:'Beginner',icon:'i-timeline',color:'#05faa8',desc:'Line up clips, arrange layers and keep timing readable.',intro:'The timeline is where your composition becomes an edit. A readable timeline makes timing changes faster and prevents accidental layer edits.',steps:[['Read the layer rows','Each row represents a layer. The clip area shows when content exists on the timeline.'],['Scrub deliberately','Move the playhead to exact moments instead of guessing where an action should begin.'],['Trim and stagger','Shorten layers that stay on screen too long and offset entrances so everything does not happen at once.'],['Keep important layers clear','Rename the character, text, overlays and audio. Group related items only after the timing is working.']],tip:'Zoom into the timeline for precise changes, then zoom back out to understand the overall pacing.',challenge:'Create a three-part sequence: background first, subject second and title last. Stagger each entrance.'},
{id:'keyframes',title:'Keyframes made simple',category:'Animation',filter:'animation',level:'Beginner',icon:'i-keyframe',color:'#82aaff',desc:'Animate position, scale, rotation and opacity with intention.',intro:'Keyframes record a property’s value at a chosen moment. The editor interpolates between keyframes, so the spacing and values shape how a movement feels.',steps:[['Pick one property','Start with position or scale on a single layer instead of animating everything at once.'],['Set the starting value','Place the playhead near the beginning and add a keyframe at the initial position or size.'],['Move to a later moment','Change the property value. If animation is enabled, a new keyframe records the new state.'],['Preview and refine','Play the movement and adjust the timing or distance until it reads clearly.']],tip:'More keyframes do not automatically mean smoother animation. Begin with two clear poses, then add detail only when needed.',challenge:'Animate an image from slightly off-screen to the center, then return it to its starting position.'},
{id:'easing-curves',title:'Easing curves & graph feel',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Make movement accelerate and settle instead of feeling robotic.',intro:'Easing changes how motion progresses between keyframes. Linear interpolation moves at a constant rate, while ease-in and ease-out curves change speed over the interval.',steps:[['Start with two keyframes','Build a simple move with a clear start and end.'],['Compare linear and eased motion','Preview both versions. Linear can feel mechanical; easing can suggest weight or intention.'],['Shape the curve','Use the available easing controls to make a gentle start, a fast middle, or a soft finish.'],['Check spacing visually','Look at how far the object travels during each part of the motion, not just the curve shape.']],tip:'For a clean stop, reduce the speed near the final pose. Too much easing can make fast edits feel sleepy.',challenge:'Create a short title entrance in three variants: linear, ease-out and ease-in-out.'},
{id:'velocity',title:'Velocity without chaos',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-bolt',color:'#82aaff',desc:'Build speed changes that feel intentional in anime and AMV edits.',intro:'Velocity is about the change in movement over time. A strong speed feel often comes from clear acceleration and deceleration, not from adding random keyframes.',steps:[['Block the main action','Set the start and end pose first, including the overall distance.'],['Control the timing','Move keyframes closer together for a sharper change and farther apart for slower movement.'],['Tune the easing','Use a sharper transition for impact, then settle into a readable pose.'],['Review at normal speed','A transition that looks impressive when paused may be too fast or confusing in playback.']],tip:'Let the viewer read the subject before the biggest speed change. Contrast makes the fast part feel faster.',challenge:'Make a text layer slide in slowly, accelerate through the center, then stop with a short settle.'},
{id:'null-objects',title:'Null objects explained',category:'Advanced',filter:'advanced',level:'Intermediate',icon:'i-layers',color:'#c4a1ff',desc:'Use a controller layer to move multiple linked layers together.',intro:'A null object can act as a controller for other layers. Parenting makes child layers follow a parent transform, which helps when several parts need to move as one system.',steps:[['Prepare the parts','Set up the image, text or shape layers you want to control together.'],['Add a null/controller','Create a null object if your version provides that feature. Give it a useful name.'],['Parent child layers','Link each layer that should follow the controller using the parenting control.'],['Animate the controller','Move or rotate the parent and check that children follow as expected.']],tip:'Keep independent details unparented when they need their own separate motion. Check pivot points before animating rotations.',challenge:'Create a simple title made from two text layers and animate them together using one controller.'},
{id:'grouping',title:'Group layers cleanly',category:'Advanced',filter:'advanced',level:'Beginner',icon:'i-layers',color:'#c4a1ff',desc:'Organize related layers and transform them without losing track.',intro:'Groups help treat multiple layers as one unit. They are useful for text assemblies, character parts and repeated design elements.',steps:[['Finish individual placement','Place each layer where it belongs before grouping.'],['Select related layers','Only group items that should share organization or transforms.'],['Create the group','Use the grouping control available in your version and name it clearly.'],['Test the result','Move, scale and rotate the group, then inspect child layers to verify that nothing shifted unexpectedly.']],tip:'If a layer appears to jump after grouping, undo once and check anchors, parent links and transform values before rebuilding.',challenge:'Build a title from a word, underline and accent shape, then group the three pieces.'},
{id:'parenting-rig',title:'Parenting & simple rigs',category:'Advanced',filter:'advanced',level:'Advanced',icon:'i-layers',color:'#c4a1ff',desc:'Connect linked layers for reusable movements and simple character parts.',intro:'Parent-child links create a hierarchy. A child’s transform is affected by its parent, which can form a simple rig for a title, icon or character assembly.',steps:[['Draw the hierarchy','Decide which layer should act as the controller and which parts should follow.'],['Link from child to parent','Choose the correct parent in the layer’s parenting controls.'],['Test each transform','Move the parent, then check that child position and rotation behave as intended.'],['Animate the rig','Add keyframes to the controller, and animate child details separately where necessary.']],tip:'Use clear names such as CTRL_Main, Head and Accent. Good naming makes complex rigs much less frustrating.',challenge:'Set up a central controller with two decorative layers that follow its movement.'},
{id:'shake-impact',title:'Impact shake that stays readable',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-bolt',color:'#82aaff',desc:'Create punchy movement around a beat or impact without overdoing it.',intro:'An impact shake works best when it supports an event. Keep the duration short, make the direction deliberate and let the shot settle after the hit.',steps:[['Find the impact frame','Place the playhead at the exact moment the hit, beat or title impact happens.'],['Add a compact movement','Animate a small position or rotation offset around the event.'],['Return to the main pose','Use a short sequence that returns the shot to a stable frame.'],['Add finish carefully','Motion blur or a subtle flash can help, but check that the subject remains readable.']],tip:'Large shake plus strong blur plus bright flash can hide the edit. Pick one dominant accent and keep the rest restrained.',challenge:'Add a very short, controlled shake to a title entrance, then make sure the title lands in a stable pose.'},
{id:'smooth-zoom',title:'Smooth zoom / push-in',category:'Animation',filter:'animation',level:'Beginner',icon:'i-keyframe',color:'#82aaff',desc:'Make a camera-like push feel smooth using scale, position and easing.',intro:'A simple push-in can be created by animating scale, sometimes paired with position to keep the subject in the right place.',steps:[['Choose the focal point','Decide what the viewer should look at before animating.'],['Set the first scale','Place the starting keyframe at the wider view.'],['Increase scale gradually','At a later time, enlarge the layer or camera view and adjust position if needed.'],['Use easing with restraint','Ease the beginning or end for a gentle camera feel. Avoid scaling so far that the image becomes visibly soft.']],tip:'If the subject drifts during the zoom, correct position at the end keyframe instead of adding many tiny ones.',challenge:'Create a slow push-in on an image, ending with the subject framed near the center.'},
{id:'motion-blur',title:'Motion blur that supports motion',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Use blur to emphasize movement rather than cover bad timing.',intro:'Motion blur adds a sense of speed during movement. It works best when the movement is already well-timed and the blur amount is not distracting.',steps:[['Polish the keyframes first','Make the motion direction and easing look right before adding blur.'],['Apply a suitable blur effect','Use the app’s available motion-blur option or a related effect, depending on your version.'],['Check the fastest moment','Scrub the most active frames and ensure important details remain readable.'],['Compare enabled and disabled','If the blur hides the subject or text, reduce it or leave it off.']],tip:'Blur is seasoning, not the main movement. A clean animation should still look good when blur is disabled.',challenge:'Compare the same short slide transition with and without blur and choose the clearer version.'},
{id:'glow-stack',title:'Clean glow stack',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Layer glow effects carefully to create bright edges without a washed-out image.',intro:'Glow can make a subject or title pop, but stacking too much glow lifts contrast and can smear details. Build the effect in small steps.',steps:[['Start with a clear subject','Choose a layer with enough contrast from its background.'],['Add one glow effect','Adjust radius, intensity or other available controls until the edge becomes visible.'],['Stack only for a reason','A second glow can provide a wider halo, while the first keeps the bright core.'],['Recheck the background','Make sure the glow does not erase the subject outline or make the whole screen look foggy.']],tip:'Keep a crisp base edge, then add a softer halo behind it. Different layers can provide separate levels of brightness.',challenge:'Create a neon title with a crisp text layer and a controlled soft halo.'},
{id:'color-grade',title:'Color grading for a consistent edit',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Keep clips and overlays feeling like they belong in the same visual world.',intro:'Color grading creates mood and consistency. It helps when the source clips have different lighting or when a sequence needs a shared palette.',steps:[['Pick the mood first','Choose a simple direction such as cool shadows and warm highlights, or a restrained monochrome look.'],['Correct before stylizing','Fix exposure and contrast problems before pushing strong color.'],['Apply a consistent treatment','Reuse similar adjustments across shots, then make small corrections per clip.'],['Check skin and key details','Ensure important colors remain natural enough for the edit’s style and readable on a phone.']],tip:'A consistent palette is usually stronger than a different heavy filter on every shot.',challenge:'Create two versions of one clip: a neutral correction and a stylized grade. Compare details side by side.'},
{id:'masking',title:'Masking for reveals',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-mask',color:'#ffbf7a',desc:'Reveal or hide parts of a layer to create clean transitions and shapes.',intro:'Masks control which parts of a layer are visible. They are helpful for title reveals, split-screen layouts and shape-based transitions.',steps:[['Plan the reveal shape','Decide whether the reveal should be a straight edge, circle, custom shape or another mask type.'],['Place the masked layer','Align the media or text beneath the mask so the reveal frames the important content.'],['Animate the mask or its source','Move, scale or reshape the mask across the timeline.'],['Check the edges','Preview at full size to catch gaps, rough edges or accidental visibility.']],tip:'Keep the mask and its target organized together. Name both layers so future edits are easy to trace.',challenge:'Create a simple left-to-right reveal for a title using a rectangular mask.'},
{id:'shake-effect-stack',title:'Build an effect stack in order',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Understand why effect order matters and avoid stacking blindly.',intro:'An effect stack is a processing chain. Earlier effects can change what later effects receive, so order can affect the final look.',steps:[['Start with the clean layer','Preview the image or text without extra effects.'],['Add the primary look','Choose the one effect that defines the style, such as blur, glow or color treatment.'],['Add supporting effects','Introduce secondary accents gradually, previewing after each change.'],['Toggle effects one by one','Disable each effect to identify what it contributes and remove anything that does not help.']],tip:'If you cannot explain what an effect contributes, turn it off and compare before deciding to keep it.',challenge:'Build a three-effect stack and write down what each effect adds to the result.'},
{id:'chromatic-split',title:'RGB split / chromatic accent',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Create a controlled color separation for a glitch or impact moment.',intro:'A chromatic split separates color edges to create a digital distortion feel. Used briefly, it can emphasize an impact. Used everywhere, it may reduce clarity.',steps:[['Choose one accent moment','Pick the frame where the effect communicates a glitch, beat or transition.'],['Apply a suitable color-separation effect','Look for chromatic aberration, RGB split or a similar effect in the available effects list.'],['Keep the duration short','Limit the effect to the moment it serves.'],['Check readability','Make sure faces, small text and important outlines remain clear enough.']],tip:'Use contrast between clean frames and distorted frames. The return to a clean image is part of the effect.',challenge:'Create a brief RGB-split moment on one title, then return to the normal title immediately after.'},
{id:'text-kinetics',title:'Kinetic typography basics',category:'Vectors & text',filter:'vectors',level:'Beginner',icon:'i-type',color:'#c4a1ff',desc:'Animate text with hierarchy, timing and deliberate entrances.',intro:'Kinetic typography combines text design and motion. Strong results come from readable words, consistent alignment and timing that supports the meaning.',steps:[['Choose a clear type scale','Use one primary typeface and set a clear distinction between main text and supporting text.'],['Break text into meaningful units','Animate a phrase, word or character only when it improves the rhythm.'],['Build the entrance','Use position, opacity or scale keyframes, then refine the easing.'],['Keep the resting pose readable','Check the final title size, alignment, spacing and contrast.']],tip:'Make the message readable before you add flashes, spins or impact effects.',challenge:'Animate a two-word title in sequence, with a clear hierarchy between the first and second word.'},
{id:'vector-drawing',title:'Vector drawing starter guide',category:'Vectors & text',filter:'vectors',level:'Beginner',icon:'i-vector',color:'#c4a1ff',desc:'Build scalable custom shapes and smooth paths in the editor.',intro:'Vector shapes are defined by paths rather than a fixed grid of pixels. They are handy for icons, custom outlines and clean graphic elements.',steps:[['Start with a simple path','Create a shape with a small number of points before attempting complicated artwork.'],['Adjust curve handles','Use path controls to smooth corners and create consistent curves.'],['Choose stroke and fill','Set a readable stroke width and a fill that contrasts with the background.'],['Refine at multiple sizes','Preview the vector at the intended output size and avoid unnecessary points.']],tip:'Fewer well-placed points usually make a cleaner path and are easier to edit later.',challenge:'Draw a simple custom icon using a few points, then add a stroke and a solid fill.'},
{id:'shape-builders',title:'Shape layers as motion graphics',category:'Vectors & text',filter:'vectors',level:'Beginner',icon:'i-vector',color:'#c4a1ff',desc:'Combine circles, lines and rectangles to build clean overlays and titles.',intro:'Shape layers can create graphic accents without importing extra artwork. Their size, fill, border and transforms can all be animated.',steps:[['Create a small shape system','Choose two or three basic shapes that fit the style you want.'],['Align using shared edges','Use consistent margins and spacing so the overlay looks intentional.'],['Animate one property per move','Scale a circle, slide a line or fade a rectangle instead of changing everything at once.'],['Group when the layout is stable','Group related pieces and test the transform after grouping.']],tip:'Simple shape motion often provides enough polish. Avoid decorating every empty space.',challenge:'Build a lower-third title using a rectangle, a line and two text layers.'},
{id:'text-outline',title:'Outline, shadow and title depth',category:'Vectors & text',filter:'vectors',level:'Beginner',icon:'i-type',color:'#c4a1ff',desc:'Give text contrast against busy clips without making it muddy.',intro:'Outlines and shadows can separate text from its background. Small, consistent treatments tend to be more readable than heavy effects.',steps:[['Pick a readable font and size','Make sure the base lettering is strong before styling it.'],['Add a subtle outline or shadow','Choose the treatment that creates enough contrast for the background.'],['Check bright and dark areas','Watch the title over several frames if the background is moving.'],['Keep styles consistent','Use the same outline or shadow logic for related text in the edit.']],tip:'The point of title styling is readability first, mood second.',challenge:'Place a title over a detailed image and compare a plain version, outline version and subtle shadow version.'},
{id:'camera-parallax',title:'Camera movement & parallax',category:'Advanced',filter:'advanced',level:'Advanced',icon:'i-layers',color:'#c4a1ff',desc:'Add depth by separating foreground, subject and background movement.',intro:'Parallax makes a scene feel deeper when different visual layers move by different amounts. It is most convincing when the source layers actually have separated depth.',steps:[['Separate scene layers','Identify a foreground, subject and background layer if the image supports it.'],['Choose a gentle camera path','A small push or pan is often enough for a short edit.'],['Offset movement by depth','Move the foreground slightly more than the background for a stronger depth cue.'],['Check for empty edges','Make sure camera movement does not reveal gaps or transparent edges.']],tip:'Parallax cannot invent missing image content. Keep movements conservative when the source is a flat image.',challenge:'Create a three-layer parallax move with only a small camera push.'},
{id:'beat-sync',title:'Beat sync without random cuts',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-bolt',color:'#05faa8',desc:'Make edits hit musical accents while preserving visual rhythm.',intro:'Beat sync is not about cutting on every beat. Strong timing uses accents, pauses and changes in energy to support the music.',steps:[['Listen before cutting','Mark the strongest beat or musical accents that matter to the sequence.'],['Place key visual changes','Use the major accents for cuts, impacts or title changes rather than every minor beat.'],['Vary the spacing','Let some shots breathe to create contrast with faster sections.'],['Preview with sound','A timeline can look well-spaced when muted but feel wrong with the actual track.']],tip:'Use a few clear accents as anchors. Variation helps the edit feel musical instead of repetitive.',challenge:'Create a short sequence with one major cut, one impact and one intentional pause matched to audio accents.'},
{id:'transitions',title:'Transitions with purpose',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-keyframe',color:'#05faa8',desc:'Choose cuts, wipes, zooms and impacts based on the scene.',intro:'A transition should connect two moments or create a specific feeling. A different flashy transition on every cut can make the sequence feel disconnected.',steps:[['Look at the two shots','Find a shared direction, color, shape or action that could connect them.'],['Pick a transition type','Use a direct cut, movement match, wipe or impact according to the action.'],['Align the timing','Make the change happen at the intended beat or action cue.'],['Review the whole sequence','Check whether the transition supports the story and pacing, not just the isolated effect.']],tip:'A well-timed cut often feels more polished than a complicated transition that does not match the motion.',challenge:'Use a movement match to connect two clips moving in the same direction.'},
{id:'xml-vs-package',title:'XML files vs Project Packages',category:'XML & files',filter:'xml',level:'Beginner',icon:'i-code',color:'#05faa8',desc:'Understand that a text file and an editable project package are not automatically interchangeable.',intro:'Editors often call shared presets or project files “XML,” but formats and import methods differ. Alight Motion provides a Project Package workflow for sharing editable projects. Do not assume every file with an XML extension can be imported as a full project.',steps:[['Check the actual file type','Look at the extension and the source. A renamed file does not become a supported preset or project format.'],['Use the correct import path','For Alight Motion Project Packages, use the official share link or QR code flow described in the Help Center.'],['Avoid blindly changing extensions','Renaming .txt or another format to .xml does not convert its contents or guarantee compatibility.'],['Keep a clean backup','Save a working copy before importing unfamiliar material into an important project.']],tip:'If a tutorial says “XML preset,” confirm the exact format and import steps for your app version before downloading anything.',challenge:'Find an official Project Package guide and write down the steps for exporting and importing a package.'},
{id:'project-package-import',title:'Import a Project Package safely',category:'XML & files',filter:'xml',level:'Beginner',icon:'i-package',color:'#05faa8',desc:'Use the official link or QR workflow and check imported projects carefully.',intro:'Alight Motion supports sharing editable projects using Project Packages. Exact steps and behavior can vary by platform or app version, so follow the current official guide.',steps:[['Get the package from a source you trust','Prefer a link shared by the creator or a known official resource.'],['Open the Alight link or scan the QR','The official flow redirects you to the app for importing.'],['Confirm the import prompt','Check the project details where available before proceeding.'],['Inspect the result','Open the project and make sure fonts, media, effects and timing behave as expected.']],tip:'A Project Package is different from a finished MP4 export. A video plays back; a package is intended to bring editable project material into the app.',challenge:'Review the official backup/import article and summarize how the share link and QR code are used.',resource:'https://support.alightmotion.com/hc/en-us/articles/13724965664785-How-do-I-back-up-my-projects'},
{id:'preset-management',title:'Preset organization that scales',category:'XML & files',filter:'xml',level:'Intermediate',icon:'i-package',color:'#05faa8',desc:'Keep reusable looks documented, named and easy to find.',intro:'A preset library becomes useful when you can identify what each preset does, where it belongs and how to apply it safely.',steps:[['Name the preset by purpose','Use labels such as “soft glow title” or “quick zoom” instead of “new preset 8.”'],['Store a preview note','Write down the intended layer type and any key controls that may need adjustment.'],['Keep a clean master copy','Test a duplicate rather than changing the only working version.'],['Review for compatibility','A preset may depend on effects, fonts or app features that are not available in every setup.']],tip:'The most reusable preset includes a clear name and a note about its intended use, not only a dramatic look.',challenge:'Create a small preset checklist with name, effect purpose, intended layer type and any limitations.'},
{id:'backup-projects',title:'Protect your projects with backups',category:'XML & files',filter:'xml',level:'Beginner',icon:'i-shield',color:'#05faa8',desc:'Build a safe habit before big edits, imports or app maintenance.',intro:'A backup gives you a way to recover editable work. Keep exported videos and editable project material separate so you do not assume one can replace the other.',steps:[['Save a clean checkpoint','Before a major experiment, duplicate or otherwise preserve the version that currently works.'],['Use official Project Package export','Follow Alight Motion’s current Project Package steps when you need a portable editable copy.'],['Store the link or QR safely','The official guide recommends keeping package details somewhere you can retrieve them.'],['Verify important backups','For valuable work, confirm that the package can be opened before you rely on it.']],tip:'Do not delete app data or reinstall assuming projects are backed up automatically. Check the official guidance first.',challenge:'Create a backup reminder checklist for before importing, major effect changes and app maintenance.',resource:'https://support.alightmotion.com/hc/en-us/articles/13724965664785-How-do-I-back-up-my-projects'},
{id:'export-quality',title:'Export quality & settings',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-download',color:'#05faa8',desc:'Choose practical resolution and quality, then inspect the result.',intro:'Export settings should match the project and destination. Higher values are not always better if the original footage or target platform does not need them.',steps:[['Match the project size','Choose a canvas size and frame rate appropriate for the final edit.'],['Pick a practical quality setting','Higher quality can increase file size and export effort. Aim for a clear result rather than the largest number.'],['Watch the exported file','Check audio sync, edge cropping, text clarity, color and the final few frames.'],['Keep an editable backup','Save the project or a Project Package when you expect to revise the edit later.']],tip:'If the export differs from preview, test a short range and compare settings before exporting the whole project again.',challenge:'Export a short test clip and check four things: sharpness, framing, audio sync and the final frame.'},
{id:'reduce-lag',title:'Reduce preview lag',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-bolt',color:'#05faa8',desc:'Make complex projects easier to preview and diagnose.',intro:'A project with many layers, high-resolution media and several effects can be demanding. A structured workflow helps you identify what is causing slow previews.',steps:[['Test the base project','Temporarily disable effect stacks to check whether the media itself plays smoothly.'],['Inspect heavy layers','Look for repeated blur, glow, large overlays or unnecessary duplicate layers.'],['Preview short sections','Work on the exact area being edited instead of repeatedly replaying the whole sequence.'],['Restore effects carefully','Turn effects back on one at a time and check when performance changes.']],tip:'Keep a clean copy before major performance experiments. Avoid deleting layers just to test; toggle visibility or effects where possible.',challenge:'Make a duplicate of a practice project and compare preview performance with nonessential effects disabled.'},
{id:'fps-framerate',title:'Frame rate explained',category:'Basics',filter:'basics',level:'Beginner',icon:'i-timeline',color:'#05faa8',desc:'Understand how frame rate affects motion, project settings and export.',intro:'Frame rate describes how many frames are shown per second. Motion cadence depends on the source footage, project frame rate and the export settings.',steps:[['Choose a target early','Set the project around the intended output and available source footage.'],['Keep settings consistent','Unnecessary changes between source, project and export can alter how motion is sampled.'],['Judge animation at playback speed','A higher number does not automatically make an animation well-timed or smooth.'],['Export a short test','Inspect motion, audio sync and file playback on the device where it will be used.']],tip:'Good keyframe spacing and easing are just as important as the frame-rate number.',challenge:'Create two short versions of the same move with different project frame rates and compare their cadence.'},
{id:'layer-naming',title:'Layer naming & project hygiene',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-layers',color:'#05faa8',desc:'Make big timelines easier to understand and revise.',intro:'A readable project reduces accidental edits. Naming, grouping and separating source material from effects layers gives you a clear map of the composition.',steps:[['Name layers by role','Use names such as Subject, Title Main, BG Texture or Light Overlay.'],['Group related pieces','Group only after the individual elements are placed correctly.'],['Keep source and polish separate','Where practical, keep the original media separate from decorative overlays or duplicated effect layers.'],['Clean as you finish','Remove unused duplicates once you are sure they are not needed and the project is saved.']],tip:'Imagine opening your project next week. Could you identify the important layers without clicking every row?',challenge:'Rename five layers in a practice project and group only the items that belong together.'},
{id:'elements-library',title:'Reusable Elements library',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-package',color:'#05faa8',desc:'Save reusable title and motion components instead of rebuilding every time.',intro:'Reusable elements can speed up repeated work. A small library of title cards, lower thirds and overlays helps create consistency across different edits.',steps:[['Find repeated work','Identify a title style, overlay or graphic that you often rebuild.'],['Create a clean reusable version','Remove one-off text and make adjustable parts easy to identify.'],['Follow the app’s element workflow','Use the available save-to-elements or reuse controls in your version.'],['Test on a new project','Confirm that the item is easy to customize and does not depend on missing media.']],tip:'A reusable element should be easy to adapt, not just a flattened copy of one finished edit.',challenge:'Create one reusable title treatment with editable text and a supporting shape.',resource:'https://alightmotion.com/elements'},
{id:'audio-visualizer',title:'Audio and visual rhythm',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-bolt',color:'#05faa8',desc:'Pair motion accents with audio without making every frame busy.',intro:'Audio can guide when a visual change happens, but visual rhythm still needs contrast, pauses and clear hierarchy.',steps:[['Choose the strongest audio cue','Listen for a beat, accent or change in energy rather than reacting to every sound.'],['Place the visual change','Align a cut, title or scale move to the cue.'],['Leave space around the accent','Use calmer motion just before or after a big change so it stands out.'],['Check the entire phrase','Look for a consistent rhythm across several seconds, not just one hit.']],tip:'Contrast makes timing feel intentional: a still moment can set up the next impact.',challenge:'Create a short edit with two accents and one quiet pause. Do not animate every beat.'},
{id:'slow-motion-feel',title:'Create a slow, controlled reveal',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Use spacing and gentle easing for cinematic movement.',intro:'A slow reveal benefits from a clear focal point and a controlled start and finish. Overly complex movement makes the shot feel less deliberate.',steps:[['Choose the focal point','Frame the viewer’s attention where it should land.'],['Use a longer motion interval','Place the starting and ending keyframes far enough apart for a gradual move.'],['Ease the movement','Choose a gentle easing curve so the motion starts or finishes softly.'],['Keep other layers quiet','Reduce competing movement while the reveal is happening.']],tip:'A slow reveal can feel powerful because the viewer has time to notice the detail, not because the effect stack is enormous.',challenge:'Reveal a subject with a gradual scale or position move and keep background motion minimal.'},
{id:'looping-animation',title:'Make a seamless loop',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Design a repeatable motion that returns cleanly to its starting state.',intro:'A seamless loop ends in a state that matches its beginning, including position, scale, rotation and visibility where relevant.',steps:[['Define the loop state','Choose the initial pose and the exact point where the loop should repeat.'],['Animate a simple path','Use a limited number of properties to keep the motion coherent.'],['Match the first and last pose','Make sure the final state meets the starting state without a visible jump.'],['Preview the repeat boundary','Watch several repeats, not just a single pass.']],tip:'For circular motion, matching only the position is not enough if rotation, opacity or scale changes at the loop point.',challenge:'Build a simple bouncing or rotating shape that repeats without a noticeable jump.'},
{id:'camera-objects',title:'Camera objects in a composition',category:'Advanced',filter:'advanced',level:'Advanced',icon:'i-layers',color:'#c4a1ff',desc:'Learn when camera-style movement helps and when a layer move is simpler.',intro:'Camera features can create a shared view movement across multiple layers. A direct layer animation may be simpler when only one object should move.',steps:[['Decide what should move','If all scene layers should share a view change, a camera may make sense.'],['Keep scene layers organized','Check layer order and depth relationships before animating the view.'],['Create a modest camera path','Start with a small pan, push or focus change.'],['Inspect framing edges','Watch for objects leaving frame or blank areas appearing during movement.']],tip:'Choose the simplest control that achieves the desired result. Not every zoom needs a camera object.',challenge:'Compare animating a single image layer with animating a camera across a small multi-layer scene.',resource:'https://support.alightmotion.com/hc/en-us/categories/10536777021713'},
{id:'troubleshoot-import',title:'Fix a project that imports strangely',category:'XML & files',filter:'xml',level:'Intermediate',icon:'i-package',color:'#05faa8',desc:'Diagnose missing fonts, media, effects or timing after importing.',intro:'Imported projects may behave differently because of app version, unavailable media, fonts or feature differences. Diagnose one problem at a time.',steps:[['Keep the original package','Do not overwrite your only copy while diagnosing problems.'],['Check missing assets','Look for missing source images, videos or fonts and replace them with compatible assets if needed.'],['Inspect unsupported effects','Some effects or controls may not match across app versions or project sources.'],['Preview sections separately','Find the first moment where the project behaves differently and investigate the layers involved.']],tip:'When asking a creator for help, share a clear description of your app version and the issue. Never share private account details.',challenge:'Create a troubleshooting checklist with project version, missing assets, effect compatibility and timing checks.'},
{id:'anime-edit-pacing',title:'Anime edit pacing & readability',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-bolt',color:'#05faa8',desc:'Build contrast between calm shots, fast accents and clear subject moments.',intro:'Anime edits can use quick movement and effects, but the viewer still needs clear subject framing and visual rhythm.',steps:[['Choose key story moments','Select the frames or actions that matter rather than using every shot equally.'],['Arrange energy levels','Place calmer frames near strong accents to create contrast.'],['Use effects to support action','Apply shake, blur or flash only where it reinforces impact.'],['Preserve subject readability','Avoid covering the key action with effects or rapid transitions.']],tip:'A strong edit gives the viewer a moment to recognize the subject before pushing into the next accent.',challenge:'Create a short sequence with one calm setup, one main impact and one clean landing frame.'},
{id:'custom-easing',title:'Design your own easing curve',category:'Animation',filter:'animation',level:'Advanced',icon:'i-curve',color:'#82aaff',desc:'Shape acceleration and deceleration for a more personal motion style.',intro:'Custom easing lets you tune how quickly a property moves through the interval between keyframes. The curve should fit the weight and intent of the object.',steps:[['Start from a clear move','Choose two keyframes with a useful distance and duration.'],['Pick the intent','Decide whether the motion should feel soft, sharp, heavy or springy.'],['Adjust the curve handles','Use the easing editor available in your version to adjust how quickly the motion accelerates and settles.'],['Preview and iterate','Change one part of the curve at a time, then watch the whole animation at normal speed.']],tip:'Do not chase a graph that looks fancy. Judge it by the movement it creates on screen.',challenge:'Make the same title entrance feel soft, sharp and heavy by changing only its easing curve.'},
{id:'project-cleanup',title:'Clean up an edit before export',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-check',color:'#05faa8',desc:'Catch small mistakes before the final render.',intro:'A short review pass can catch timing, framing and asset mistakes that are easy to miss while actively editing.',steps:[['Play from the beginning','Watch the edit without stopping so you notice pacing issues.'],['Inspect the edges','Check titles, shapes and subjects at the project boundaries.'],['Check audio and transitions','Look for sudden cuts, missing audio, unintended gaps or effects that continue too long.'],['Review the exported file','Verify the actual output rather than trusting preview alone.']],tip:'A 30-second review checklist can save a full re-export.',challenge:'Create a personal pre-export checklist with framing, text, audio, effects and final frame.'},
{id:'canvas-ratio',title:'Choose the right canvas ratio',category:'Basics',filter:'basics',level:'Beginner',icon:'i-grid',color:'#05faa8',desc:'Match the project frame to where the edit will be viewed.',intro:'Canvas ratio affects framing, negative space and how safely the composition survives platform crops. Pick it before detailed positioning.',steps:[['Choose the destination','Decide whether the piece is vertical, square or landscape before importing lots of assets.'],['Set the canvas deliberately','Use a standard ratio such as 9:16 for vertical or 16:9 for landscape, then choose a suitable resolution.'],['Keep a safe zone','Keep faces and essential text away from the extreme edges because previews and platforms may crop differently.'],['Preview on a phone-sized view','Shrink the canvas preview and check whether the focal subject and title remain readable.']],tip:'Changing the canvas late can reposition the composition. Save a copy before making a major ratio change.',challenge:'Make the same title card in vertical and landscape layouts, then recompose instead of simply shrinking everything.'},
{id:'clip-trim',title:'Trim layers without losing timing',category:'Basics',filter:'basics',level:'Beginner',icon:'i-timeline',color:'#05faa8',desc:'Trim entrances and exits so each layer appears for the right reason.',intro:'Layer duration controls when material is visible on the timeline. Clean trims reduce dead frames and help pacing feel intentional.',steps:[['Find the useful range','Scrub the layer and note where the content actually begins and ends.'],['Trim the unused part','Use the layer edge or trim command available in your version to remove empty lead-in or tail frames.'],['Check transitions','Make sure the outgoing layer remains visible long enough to connect to the next shot.'],['Preview the boundary','Play a second before and after the trim to catch flashes or accidental gaps.']],tip:'Trim after the rough sequence is placed. If you trim too early, you may lose context for a transition.',challenge:'Build a three-shot sequence and remove any dead frames between the three entrances.'},
{id:'layer-order',title:'Understand layer order and overlap',category:'Basics',filter:'basics',level:'Beginner',icon:'i-layers',color:'#05faa8',desc:'Control what appears in front and what sits behind.',intro:'Layer order determines how overlapping visuals are composited. A correct layer stack can matter more than another effect.',steps:[['Separate background and foreground','Place backgrounds beneath subjects and foreground accents above the areas they should cover.'],['Test overlap deliberately','Move one layer across another to understand which item is drawn on top.'],['Keep masks with their target','Check the target layer and the mask relationship after moving or grouping layers.'],['Name important rows','Labels such as BG, SUBJECT, TEXT and FX help you read the stack quickly.']],tip:'If a glow or overlay disappears, check layer order and blending before rebuilding the effect.',challenge:'Create a composition with a background, subject, title and light overlay, then reorder the stack to compare results.'},
{id:'anchor-point',title:'Anchor points and pivot control',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-keyframe',color:'#82aaff',desc:'Make rotation and scale happen around the intended point.',intro:'The anchor or pivot point affects the way a layer rotates and scales. A poor pivot can make a simple animation look like it is orbiting unexpectedly.',steps:[['Pick the movement','Rotation around the center looks different from rotation around a corner or joint.'],['Set or understand the pivot','Use the transform controls provided in your version to position the anchor if available.'],['Test with a small rotation','Rotate a few degrees and inspect the path before creating a long animation.'],['Adjust before easing','Fix the pivot and pose first, then fine-tune curve timing.']],tip:'For a character or mechanical part, place the pivot near the joint that should act as the hinge.',challenge:'Animate a card rotating open from a corner, then repeat it using the center as its pivot.'},
{id:'opacity-fades',title:'Clean fades with opacity keyframes',category:'Animation',filter:'animation',level:'Beginner',icon:'i-keyframe',color:'#82aaff',desc:'Reveal and remove layers without sudden pops.',intro:'Opacity animation controls how visible a layer is over time. Small, well-timed fades can make transitions feel less abrupt.',steps:[['Set a visible end state','Choose the target opacity for the moment the layer should be fully visible.'],['Set the start value','At the start of the reveal, set opacity low or at zero if appropriate.'],['Choose a short interval','Use a few frames for a snappy reveal or a longer interval for a soft appearance.'],['Check against the background','A fade can look different on light and dark backgrounds, so test it in context.']],tip:'Opacity fades are often more readable when paired with a small position or scale change, not five unrelated effects.',challenge:'Fade a title in, hold it long enough to read, then fade it out before the next title arrives.'},
{id:'staggered-entrances',title:'Staggered text and layer entrances',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-timeline',color:'#82aaff',desc:'Make multiple parts arrive in a clear visual sequence.',intro:'Staggering means offsetting similar animations in time. A small delay gives the eye a path through the composition and avoids everything popping at once.',steps:[['Choose an order','Decide what the viewer should see first, second and last.'],['Build one clean movement','Animate the first layer well before duplicating the same idea to other layers.'],['Offset start times','Move each layer’s animation a little later on the timeline.'],['Adjust the gap','Shorten delays for energetic motion and increase them for a calm sequential reveal.']],tip:'Stagger by a consistent small interval at first, then break the pattern only for a clear reason.',challenge:'Animate three words so they enter one after another and finish in a balanced layout.'},
{id:'overshoot-settle',title:'Overshoot and settle motion',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Add a controlled overshoot so a move feels lively, not sloppy.',intro:'Overshoot carries an object slightly past its destination before it returns to rest. The effect is strongest when the overshoot is small and the final pose is clear.',steps:[['Choose a destination','Create the main move and establish a final resting pose.'],['Add a slight overshoot','Place a brief intermediate pose a little beyond the destination.'],['Return to the final pose','Add a short correction keyframe so the layer settles exactly where intended.'],['Reduce the distance','If it feels rubbery or messy, reduce the overshoot rather than adding more keyframes.']],tip:'Use stronger overshoot for soft, playful objects and little or none for heavy, precise typography.',challenge:'Make a title slide to its resting position, pass it slightly, and settle back smoothly.'},
{id:'anticipation-followthrough',title:'Anticipation and follow-through',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Make a movement feel prepared and complete.',intro:'Anticipation prepares the viewer for an action; follow-through lets secondary parts finish after the main move. Both are ways of adding clear cause and effect.',steps:[['Add a small preparation','Before the main move, shift or scale the subject slightly in the opposite direction.'],['Deliver the main action','Keep the primary motion clear and avoid making the preparation longer than the action needs.'],['Add a gentle follow-through','Let a secondary detail settle just after the main subject reaches its pose.'],['Review the action at full speed','Make sure the preparation reads as intentional rather than a glitch.']],tip:'Anticipation should help the viewer predict the action, not distract from it.',challenge:'Animate a title that compresses slightly, pushes forward, and lets a small accent settle afterward.'},
{id:'rotation-orbit',title:'Rotation versus orbit movement',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Tell the difference between spinning an object and moving it around a center.',intro:'Rotation changes a layer’s angle around its pivot. Orbiting requires the object’s position to travel around a center point, which is a different path.',steps:[['Test rotation alone','Rotate the layer while its position stays fixed.'],['Plan an orbit path','Use position keyframes to move the object around a center, or use an appropriate parent/controller if available.'],['Coordinate angle and position','Let the angle support the movement, but do not rotate so much that the subject becomes hard to read.'],['Review the path','Check the object’s distance from the center for consistency.']],tip:'A circular position path and a changing layer angle are separate ideas; use whichever one the visual needs.',challenge:'Create a dot that travels around a title while keeping the title fixed.'},
{id:'position-vs-scale',title:'Position vs scale: choose the right move',category:'Animation',filter:'animation',level:'Beginner',icon:'i-keyframe',color:'#82aaff',desc:'Use movement or zoom based on what the shot needs to communicate.',intro:'Position moves an object through the frame; scale changes its size. They can be combined, but mixing both without a clear purpose makes the motion feel unstable.',steps:[['Decide what should feel closer','Use scale or a camera-style push to suggest a change in distance.'],['Decide what should travel','Use position when the subject needs to move to a new location.'],['Try them separately first','Preview a position-only version and a scale-only version before combining both.'],['Keep the focal point stable','If scaling, check whether the subject’s anchor keeps the intended point in place.']],tip:'A tiny scale increase can feel more like a camera push when combined with careful easing and subtle position adjustment.',challenge:'Make two entrances for the same title: one positional slide and one scale push. Compare their feel.'},
{id:'text-baseline',title:'Typography hierarchy for edits',category:'Vectors & Text',filter:'vectors',level:'Beginner',icon:'i-type',color:'#ff8fb1',desc:'Give titles a clear main line, supporting line and readable spacing.',intro:'Typography hierarchy is the order in which the viewer notices text. Size, weight, contrast, spacing and placement should work together.',steps:[['Pick one headline','Choose the most important phrase and make it the visual anchor.'],['Reduce supporting text','Use a smaller or lighter style for secondary labels and credits.'],['Check contrast','Text must remain readable against the image and any effects behind it.'],['Preview small','If the title becomes unclear when viewed as a small thumbnail, simplify it.']],tip:'One strong type treatment usually beats several competing fonts, outlines and glows.',challenge:'Design a title card with one headline and one small secondary label using only two font weights.'},
{id:'text-safe-area',title:'Text safe zones and phone readability',category:'Vectors & Text',filter:'vectors',level:'Beginner',icon:'i-type',color:'#ff8fb1',desc:'Keep essential text readable and away from interface overlays.',intro:'Mobile platform interfaces can cover edges of the video. A title that fits the canvas can still be obscured when posted.',steps:[['Keep a margin','Avoid placing important words directly at the top, bottom or extreme sides.'],['Use a quick readability check','Preview at the actual phone size rather than zoomed all the way in.'],['Separate decorative text','Keep the main message visually distinct from tiny labels and credits.'],['Check the final crop','Use a mock platform preview if you have one, but always inspect the exported clip.']],tip:'The safest area varies by platform and format, so keep extra room when the edit will be reposted in multiple places.',challenge:'Move a title inward from the edges and compare readability in a small preview.'},
{id:'blend-modes',title:'Blend modes without guesswork',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Use blending to combine light, texture and footage with control.',intro:'Blend modes change how a layer’s pixels combine with the layers below. The same overlay can look very different depending on the mode and opacity.',steps:[['Start with a simple overlay','Use a light, texture or color layer with a clear purpose.'],['Compare a few modes','Try a lightening or darkening mode appropriate to the content, where available in your app version.'],['Adjust opacity afterward','A blend mode may work best at reduced opacity rather than full strength.'],['Inspect skin and highlights','Check that important detail has not disappeared or clipped.']],tip:'Do not assume a named blend mode behaves identically for every color and background. Preview it on the actual shot.',challenge:'Compare normal blending and two other blend modes on the same light overlay, then choose the most controlled result.'},
{id:'gradient-fills',title:'Gradient fills with a focal point',category:'Effects & style',filter:'effects',level:'Beginner',icon:'i-effect',color:'#ffbf7a',desc:'Guide attention with a gradient instead of a flat color wash.',intro:'Gradients create a controlled transition between colors. Position, direction and contrast determine whether they support or compete with the subject.',steps:[['Pick a purpose','Use a gradient to frame a subject, separate text from the background or add a subtle atmosphere.'],['Choose a restrained palette','Start with two related colors or one accent fading into transparency if available.'],['Position the focal point','Keep the brighter or more saturated area near the element you want noticed.'],['Reduce intensity','Lower opacity or contrast if the gradient becomes the main subject.']],tip:'Gradients often work best as background support. Keep important text contrast strong.',challenge:'Create a two-color background gradient that frames a central subject without making the subject hard to read.'},
{id:'shadow-depth',title:'Shadows for separation and depth',category:'Effects & style',filter:'effects',level:'Beginner',icon:'i-effect',color:'#ffbf7a',desc:'Separate titles and shapes from the background with a deliberate shadow.',intro:'A shadow can imply depth or improve readability. It becomes distracting when the offset, softness or opacity is too strong for the scene.',steps:[['Set the layer and background','Check how much natural contrast already exists.'],['Start with a short offset','Move the shadow only enough to separate the object.'],['Tune softness and strength','Use blur and opacity, if offered, until the edge feels appropriate.'],['Check for double edges','Avoid stacking multiple shadows that create a dirty outline unless that is the intentional style.']],tip:'For readability, a subtle shadow is not a substitute for good text contrast.',challenge:'Apply a subtle shadow to a title, then reduce the offset until the text feels grounded rather than floating.'},
{id:'grain-texture',title:'Add texture without muddying the edit',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Use grain and texture as a finishing layer, not as visual noise.',intro:'Texture can unify flat elements or help a style feel tactile. Too much texture reduces clarity, especially after platform compression.',steps:[['Choose a subtle source','Use a low-contrast grain or texture layer.'],['Place it intentionally','Decide whether the texture belongs over the whole scene or only selected elements.'],['Lower the intensity','Reduce opacity and compare with the original image.'],['Inspect export sharpness','Texture that looks fine in preview can become noisy after compression.']],tip:'Toggle the texture on and off. If the edit is not improved, remove it.',challenge:'Create two versions of the same frame, with subtle texture and without it, then compare at phone size.'},
{id:'particles-control',title:'Particles and overlays with restraint',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Keep extra motion from covering the subject.',intro:'Particles, dust and overlays can add atmosphere, but multiple moving layers compete for visual attention if they are all equally strong.',steps:[['Choose one visual purpose','For example, add depth, imply energy or soften a transition.'],['Keep the subject dominant','Place the densest or brightest particles away from important facial features and text.'],['Reduce count or opacity','Lower intensity until you can still read the main shot.'],['Check motion continuity','Avoid a sudden switch from no particles to a very dense overlay unless it is part of the beat.']],tip:'A few particles with clear direction often read better than a full frame of random movement.',challenge:'Add one particle overlay to a shot and tune it until the focal point stays clear.'},
{id:'chroma-key',title:'Green-screen / chroma key basics',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-mask',color:'#ffbf7a',desc:'Understand what makes keying footage cleaner.',intro:'Chroma key removes a selected color range from footage. The quality depends on the source lighting, edges, spill and available key controls.',steps:[['Use clean source footage','Even lighting and separation from the background make keying easier.'],['Choose the background color range','Use the keying effect or feature available in your version and sample the intended color.'],['Inspect the edges','Look for leftover background, holes in the subject or jagged edges.'],['Refine spill and feathering','Make small adjustments to edge and spill controls where available; avoid erasing fine detail.']],tip:'Do not try to fix badly lit footage only with aggressive settings. Source quality matters.',challenge:'Practice on a short sample with a solid background and inspect hair or fine edges before adding effects.'},
{id:'compositing-order',title:'Compositing order: subject, light, grade',category:'Effects & style',filter:'effects',level:'Advanced',icon:'i-layers',color:'#c4a1ff',desc:'Create a predictable stack by separating visual jobs.',intro:'Compositing is how multiple visual elements combine into a final frame. A deliberate layer and effect order makes the result easier to tune.',steps:[['Build the base image','Make sure source footage or artwork looks correct before styling.'],['Add light or atmosphere','Keep glows, overlays and blur on the layers where they are meant to affect the scene.'],['Finish with a consistent grade','Use color adjustments to unify the image without removing important detail.'],['Toggle stages individually','Check base, atmosphere and grading separately to find what each layer contributes.']],tip:'Keep your effects modular where practical; changing the whole stack at once makes it hard to diagnose problems.',challenge:'Build a small composition with base, light overlay and finishing color adjustment, then compare each stage.'},
{id:'vector-paths',title:'Vector paths and nodes',category:'Vectors & Text',filter:'vectors',level:'Intermediate',icon:'i-vector',color:'#ff8fb1',desc:'Understand nodes and path segments when drawing shapes.',intro:'Vector paths are built from points connected by straight or curved segments. A small number of well-placed nodes is easier to edit than a path with too many points.',steps:[['Start with the silhouette','Use as few points as practical to define the main form.'],['Place corners deliberately','Use corner nodes for sharp changes and curve handles for smooth bends where available.'],['Inspect at different sizes','Zoom in to check corners and zoom out to judge the overall shape.'],['Keep paths editable','Save a clean version before adding detailed decoration.']],tip:'More nodes create more chances for lumpy curves. Add a point only when the shape needs it.',challenge:'Draw a simple leaf or lightning-bolt shape using a small number of points.'},
{id:'bezier-handles',title:'Bézier handles for smoother vectors',category:'Vectors & Text',filter:'vectors',level:'Advanced',icon:'i-vector',color:'#ff8fb1',desc:'Use curve handles to control direction and smoothness.',intro:'Bézier handles determine how a curved path leaves and approaches a node. Their direction and length influence how soft or tight a curve feels.',steps:[['Choose a curved section','Pick a shape with a bend that looks too sharp or uneven.'],['Align the handles with the curve','Keep handles pointing in the direction the path should flow as it enters and leaves the node.'],['Adjust handle length','Longer handles generally make the curve broader; shorter ones allow tighter bends.'],['Inspect neighboring segments','One smooth node can still create a poor transition if the next segment changes direction abruptly.']],tip:'Work on the silhouette first. Fine details will not rescue an uneven main contour.',challenge:'Refine a curved vector letter or icon until there are no accidental kinks.'},
{id:'stroke-animation',title:'Animate a stroke reveal',category:'Vectors & Text',filter:'vectors',level:'Intermediate',icon:'i-vector',color:'#ff8fb1',desc:'Create the feeling of a line being drawn on screen.',intro:'A stroke reveal gives a vector path the appearance of drawing itself. Depending on your app version and setup, it may use path trim, masking or another reveal method.',steps:[['Create a simple path','Start with a line, circle or short vector illustration.'],['Choose a reveal technique','Use a stroke/trim control if available, or animate a mask that reveals the path.'],['Animate from hidden to visible','Set the start and end of the reveal across a chosen interval.'],['Check corners and end caps','Keep the reveal direction and final endpoint clean.']],tip:'A simpler path is easier to reveal smoothly. Add multiple stroke layers only after the first is working.',challenge:'Reveal a line or circle over one second and time the end of the draw to a visual accent.'},
{id:'shape-morph-plan',title:'Plan a shape morph',category:'Vectors & Text',filter:'vectors',level:'Advanced',icon:'i-vector',color:'#ff8fb1',desc:'Prepare two shapes so a transformation looks intentional.',intro:'A shape morph changes one form into another. Support depends on the tool and property types available, so some projects need a mask or transition rather than a direct path morph.',steps:[['Choose related silhouettes','Start with two simple forms that share a similar visual structure.'],['Match point flow where possible','A clean transition is easier when corresponding points travel in sensible directions.'],['Test a short transition','Use the available path animation or masking technique in your version.'],['Simplify if it twists','If the shape crosses over itself, adjust the path or use a designed transition between the two forms.']],tip:'Do not assume every pair of vector shapes can interpolate cleanly. A deliberate mask transition can look better than a broken morph.',challenge:'Design a circle-to-diamond transition using whatever compatible path or mask technique your app supports.'},
{id:'logo-sting',title:'Build a tiny logo animation',category:'Vectors & Text',filter:'vectors',level:'Intermediate',icon:'i-spark',color:'#ff8fb1',desc:'Animate a mark with a clear entrance, hold and exit.',intro:'A logo sting is a short brand-style animation. It needs one memorable motion idea and a readable final state.',steps:[['Simplify the mark','Use a clean silhouette and avoid too many tiny elements.'],['Choose an entrance','Reveal, slide or scale the mark with a clear path.'],['Hold the final pose','Give the viewer enough time to identify it.'],['Exit only if needed','If the sting leads into another shot, choose a transition that supports the next scene.']],tip:'Keep a clean version with no extra glow or trails so the mark remains flexible for future edits.',challenge:'Animate a simple shape or initials in two seconds with a readable final hold.'},
{id:'xml-file-basics',title:'What an XML file actually is',category:'XML & files',filter:'xml',level:'Beginner',icon:'i-code',color:'#05faa8',desc:'Understand XML as structured text, not a universal preset format.',intro:'XML is a text format for structured data. Whether an XML file can be used by Alight Motion depends on the expected schema, app version and what the file represents.',steps:[['Check the file source','Confirm where the file came from and what app or version it targets.'],['Inspect its extension and contents','A file name alone does not prove it is a compatible preset or project.'],['Prefer known sharing flows','Use the app’s supported project package or sharing method when one is provided.'],['Keep a backup before import','Unknown or incompatible files may fail to load or behave differently than expected.']],tip:'Never assume that renaming a file to .xml converts it into a valid Alight Motion resource.',challenge:'Use the XML inspector in this hub on a harmless sample XML file and review what it can and cannot prove.'},
{id:'qr-package-sharing',title:'Share editable projects safely',category:'XML & files',filter:'xml',level:'Beginner',icon:'i-package',color:'#05faa8',desc:'Know the difference between exporting a video and sharing an editable project.',intro:'A rendered video is a flattened result. A project package is intended to preserve editable structure when supported by the app. They serve different purposes.',steps:[['Decide what the recipient needs','If they only need to watch, send a rendered video. If they need to edit, use the app’s supported project-sharing flow.'],['Check included assets','Fonts, media and app features may not transfer exactly in every project.'],['Give the recipient context','Mention app version, missing assets and any effects that need manual replacement.'],['Test the share before deleting originals','Open the shared copy where possible and keep your source project.']],tip:'A screenshot of a QR code or a text file is not the same thing as a confirmed editable project package.',challenge:'Write a short handoff note for a practice project that lists the target version, assets and editing goal.'},
{id:'version-compatibility',title:'Handle version differences calmly',category:'XML & files',filter:'xml',level:'Intermediate',icon:'i-package',color:'#05faa8',desc:'Troubleshoot missing controls and effects between app versions.',intro:'App versions can vary in menus, effect availability, feature behavior and device support. A guide from another version may show a different button or screen.',steps:[['Check the guide date and app version','Use current official help resources when the screen does not match.'],['Find the feature by function','Search the official Help Center for the feature name rather than relying only on an icon location.'],['Test on a duplicate project','Avoid converting or overwriting the only project copy while testing compatibility.'],['Replace unsupported effects carefully','Choose a similar supported effect and retune it rather than stacking random replacements.']],tip:'A slightly different menu is not automatically a broken project. Verify behavior before changing several settings.',challenge:'Pick one tutorial, note which interface controls vary on your device, and find the current official feature guide.'},
{id:'assets-and-fonts',title:'Prevent missing assets and fonts',category:'XML & files',filter:'xml',level:'Intermediate',icon:'i-package',color:'#05faa8',desc:'Make projects easier to transfer by tracking media and typefaces.',intro:'Projects may rely on source media, fonts and linked assets. A recipient may not have the same files or fonts, even if the project structure transfers.',steps:[['List the used assets','Note source video, images, audio and any custom fonts.'],['Check each important media item','Confirm files are present and still play before packaging.'],['Choose a font fallback','Where a font may be unavailable, document a close substitute if editable text matters.'],['Reopen the shared copy','When possible, test the package on another project or device before deleting sources.']],tip:'A project is more portable when the assets and dependencies are known instead of hidden in the editor’s history.',challenge:'Make a short asset checklist for a project with a video, title font, audio track and overlay.'},
{id:'export-test-range',title:'Use a short export test',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-download',color:'#05faa8',desc:'Catch export mistakes before rendering a long project.',intro:'A short test render can reveal the wrong frame rate, audio issues, missing media, cropping or heavy compression without wasting a full export.',steps:[['Choose a representative segment','Include motion, effects, text and audio if the project uses them.'],['Export with the intended settings','Use the same quality and frame-rate settings planned for the full edit.'],['Review the actual file','Do not rely only on the in-app preview. Watch the test on the target device.'],['Change one thing at a time','If something looks wrong, modify one setting and repeat the short test.']],tip:'Test a section with the most demanding effects, not only the easiest part of the timeline.',challenge:'Export a 2-3 second section and check sharpness, audio sync, framing and playback.'},
{id:'file-size-planning',title:'Manage export size without guessing',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-download',color:'#05faa8',desc:'Balance clarity, duration and file size for the intended platform.',intro:'File size is influenced by duration, resolution, frame rate, codec and compression settings. You cannot judge quality from a file size alone.',steps:[['Match the destination','Use a resolution and frame rate suited to the platform and source footage.'],['Avoid needless upscaling','Making a smaller source much larger does not recreate lost detail.'],['Compare short tests','Export a representative clip with two sensible quality settings and inspect the difference.'],['Check motion and gradients','Compression artifacts often show in fast motion, fine detail and smooth color ramps.']],tip:'Choose quality by visually checking the final file, not just by picking the largest available option.',challenge:'Compare two short exports and identify whether the larger file shows a meaningful improvement.'},
{id:'platform-reframing',title:'Reframe one edit for multiple platforms',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-grid',color:'#05faa8',desc:'Adapt the composition instead of stretching the same layout everywhere.',intro:'Different canvas ratios change the relationship between text, subjects and negative space. Reframing is often better than uniformly scaling the original composition.',steps:[['Duplicate the project','Keep the original layout as your source.'],['Choose the new ratio','Set the next canvas to the target format.'],['Reposition focal elements','Move subjects and titles while preserving the visual hierarchy.'],['Check crops and holds','Make sure the new framing has no clipped text or awkward empty area.']],tip:'If the edit contains several shots, check every shot after reframing. A crop that works in one scene may break the next.',challenge:'Recompose a title card from vertical to landscape and keep the headline equally readable.'},
{id:'creative-credits',title:'Credit creators and respect assets',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-heart',color:'#05faa8',desc:'Keep track of references, fonts, overlays and project inspirations.',intro:'Using a reference to learn is different from claiming another creator’s assets as your own. Check the creator’s terms before reusing their project, overlay or preset.',steps:[['Record the source','Save the creator name and original public link when you download or reference an asset.'],['Check permission and terms','Look for reuse rules, credit requirements and limits on redistribution.'],['Keep attribution accurate','Do not label a recreated technique as the original creator’s downloadable preset.'],['Share responsibly','Remove private information and avoid reuploading someone else’s work without permission.']],tip:'A short source note in your project folder makes attribution much easier later.',challenge:'Create a source note for three reference assets and state whether each is for learning, licensed reuse or inspiration only.'},
{id:'accessibility-contrast',title:'Make titles readable with contrast',category:'Vectors & Text',filter:'vectors',level:'Beginner',icon:'i-type',color:'#ff8fb1',desc:'Keep text legible over bright, busy or fast-moving footage.',intro:'Readable text needs enough difference from the background in brightness, color or outline. Decorative effects should not make essential words harder to read.',steps:[['Find the busiest frame','Check the title over the brightest and most detailed part of the shot.'],['Increase separation','Use a solid backing, restrained shadow or position change if necessary.'],['Check size and weight','Avoid very thin type for small mobile text.'],['Review without pausing','The title should be readable at normal playback speed.']],tip:'A visually stylish title can still fail its purpose if the audience cannot read it.',challenge:'Place the same title over a dark and a bright frame, then adjust placement and contrast so it reads in both.'},
{id:'fx-versioning',title:'Keep reusable effect recipes organized',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-package',color:'#05faa8',desc:'Document settings and versions instead of relying on memory.',intro:'An effect recipe is only useful if you can rebuild it. Record the goal, order and notable values for each repeatable treatment.',steps:[['Give the treatment a purpose-led name','Use names such as Soft Title Glow or Quick Impact Blur.'],['Record order and key values','Write down the effect order and the settings that noticeably change the result.'],['Note app/version context','Record when a control depends on a feature available only in certain versions.'],['Retest on a different clip','A recipe may need adjustment for footage with different lighting or colors.']],tip:'Store a clean before-and-after example with your notes so you can judge whether the recipe still helps.',challenge:'Document one effect stack with its purpose, order, adjustment notes and one limitation.'},
{id:'timing-holds',title:'Use holds to make edits readable',category:'Animation',filter:'animation',level:'Beginner',icon:'i-timeline',color:'#82aaff',desc:'Give the viewer time to recognize the subject and read the text.',intro:'A hold is a short period where a pose or composition remains relatively stable. Holds create contrast with movement and let the viewer process a moment.',steps:[['Identify the main information','Decide what the viewer must understand before the next movement.'],['Leave a stable interval','Avoid constantly moving the title or subject during the hold.'],['Make the next action distinct','Use the next transition to change the visual state clearly.'],['Watch with fresh eyes','If a title is readable only when paused, lengthen the hold or reduce its text.']],tip:'Fast editing does not mean every frame needs a new motion. Stability helps speed feel stronger.',challenge:'Create a short edit with a sharp entrance, a readable hold and a clear exit.'},
{id:'motion-direction',title:'Use consistent motion direction',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Make transitions feel connected by preserving screen direction.',intro:'Direction continuity helps the viewer understand relationships between shots. Randomly reversing every movement can make a sequence feel disorienting.',steps:[['Choose an overall direction','Decide whether the sequence generally pushes, sweeps or travels across the frame.'],['Carry direction into the next shot','Let the exit or movement suggest where the next shot can enter from.'],['Break direction with purpose','A reversal can signal impact or change, but should not happen accidentally.'],['Check the whole sequence','Preview several transitions together, not just each one in isolation.']],tip:'Direction continuity is a visual guide, not a rule. Break it when the story or beat benefits.',challenge:'Build two connected shots where the outgoing movement leads naturally into the incoming one.'},
{id:'blur-direction',title:'Match blur to the direction of motion',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Use blur to support speed rather than obscure detail.',intro:'Directional blur can reinforce movement, but blur that disagrees with the path may feel disconnected. Too much blur hides the action.',steps:[['Establish the path first','Confirm where the subject moves before adding blur.'],['Use blur as support','Add or tune blur on the movement interval rather than making every frame equally soft.'],['Check the resting pose','Keep the final pose crisp enough to read.'],['Preview at full speed','Watch for smeared text, faces or important edges.']],tip:'The movement and timing should sell the action even if the blur is turned off.',challenge:'Compare the same slide with no blur, a subtle blur and a heavy blur. Keep the strongest readable option.'},
{id:'color-harmony',title:'Build color harmony across clips',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Connect different source shots with a consistent palette.',intro:'Color harmony comes from consistent relationships among hue, saturation and contrast. It does not mean every shot must use the exact same filter.',steps:[['Pick an anchor color','Choose a main accent or mood based on the scene.'],['Adjust one shot at a time','Correct extreme differences before adding a creative color style.'],['Keep skin and highlights readable','Avoid pushing every shot toward one hue if it destroys important detail.'],['Compare the sequence','Switch between neighboring shots to check whether they feel related.']],tip:'Use the palette tool in this hub to try color directions before adjusting the footage.',challenge:'Choose three colors for an edit and apply them consistently to title, accents and background treatments.'},
{id:'beat-contrast',title:'Create contrast around the beat',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-bolt',color:'#05faa8',desc:'Make a beat hit feel strong by changing motion density around it.',intro:'A visual accent feels stronger when the preceding and following moments are simpler. If every moment is equally intense, the beat loses contrast.',steps:[['Find the strongest cue','Choose one musical accent that supports the edit.'],['Build a lead-in','Use a stable shot or restrained motion before the cue.'],['Place one clear action','Use a cut, scale impact or text reveal at the accent.'],['Let the moment breathe','Hold or simplify after the hit before the next burst of motion.']],tip:'A beat grid is only a guide. Listen to the actual track and use the phrase, not just an automatic interval.',challenge:'Build a sequence with one emphasized beat and a calmer moment on either side.'},
{id:'transition-direction',title:'Design transitions around the incoming shot',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Make the transition deliver the next shot rather than distract from it.',intro:'A transition should connect visual information. Direction, color and scale can anticipate the incoming shot and lead the eye into it.',steps:[['Inspect both shots','Identify a shared direction, color or shape that can bridge them.'],['Choose one main transition idea','Start with a wipe, move or short blur rather than combining every transition type.'],['Time the reveal','Make the new shot readable once it arrives.'],['Remove decoration that does not help','The transition should clarify the cut or add energy, not hide a timing problem.']],tip:'If the two shots do not connect, a clean cut may work better than a complicated transition.',challenge:'Design two versions of one cut: a clean cut and a single-effect transition. Compare clarity.'},
{id:'keyframe-spacing',title:'Read keyframe spacing visually',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-keyframe',color:'#82aaff',desc:'Understand how timing gaps and property changes shape motion.',intro:'Keyframe spacing on the timeline controls when changes happen, while the difference between values controls how far the object moves. Both affect perceived speed.',steps:[['Keep one variable simple','Use the same start and end values for a clean test.'],['Change the time gap','Move the end keyframe closer for a faster interval and farther away for a slower one.'],['Then change distance','Keep timing similar and change the final position or scale.'],['Compare playback','Notice which edit changes speed and which changes travel distance.']],tip:'Do not judge timing only from how many keyframes you see. Preview the motion at actual speed.',challenge:'Make two moves with the same distance but different durations, then two moves with the same duration but different distances.'},
{id:'mask-reveal',title:'Use masks for a clean reveal',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-mask',color:'#ffbf7a',desc:'Reveal part of an image or title with a controlled shape.',intro:'Masking controls which parts of a layer are visible. The exact setup depends on the app version and mask type, so start with a simple shape and a single target layer.',steps:[['Choose what should appear','Pick a subject or title and decide the direction of the reveal.'],['Create or add the mask','Use the mask controls supported by your version.'],['Animate the mask boundary','Move, scale or reveal the mask to uncover the target.'],['Check edges','Look for unexpected holes, reversed visibility or hard edges that do not fit the style.']],tip:'Make sure the mask affects the intended layer. If nothing changes, verify the mask-target relationship before adding more effects.',challenge:'Reveal a title from left to right using a mask or another compatible reveal method.'},
{id:'export-frame-rate',title:'Avoid mismatched frame-rate exports',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-download',color:'#05faa8',desc:'Keep cadence consistent between project, source and final render.',intro:'Frame-rate mismatch can change cadence, duplicate or skip samples, and affect how motion appears. The best setting depends on the source and intended destination.',steps:[['Check the source media','Know the frame rate of footage if it matters to the edit.'],['Choose the project target','Set a frame rate for the intended final output rather than changing it without reason.'],['Match the export where practical','Review export options and make an intentional choice.'],['Inspect fast motion','Fast pans or repeated flashes are good places to detect uneven cadence.']],tip:'A higher FPS number is not a universal fix for choppy animation. Keyframe timing and source footage matter too.',challenge:'Create two short tests using different frame-rate settings and compare the same fast movement.'},
{id:'local-workflow-backup',title:'Create a safe revision workflow',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-package',color:'#05faa8',desc:'Keep versions so experiments never destroy your best edit.',intro:'A reliable revision workflow creates checkpoints before risky changes. It is easier to experiment when you can return to a known-good version.',steps:[['Save a baseline','Keep an untouched copy before heavy effect changes or cleanup.'],['Name milestones','Use simple names such as Draft, MotionPass and FinalReview.'],['Change one class of setting','Adjust timing first, then effects or color, so you know what improved.'],['Verify the final package','Make sure the saved project opens and the exported video plays before cleaning old copies.']],tip:'Do not rely on one export as your only copy of a project you may need to edit again.',challenge:'Create a 3-stage version plan for a short practice edit, with a reason for each checkpoint.'},
{id:'audio-level-check',title:'Check audio levels and sync',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-bolt',color:'#05faa8',desc:'Make sure the audio supports the edit without clipping or drifting.',intro:'Audio sync and loudness affect how polished an edit feels. A visually strong sequence can still feel unfinished if the soundtrack starts late or cuts off harshly.',steps:[['Check the first sound','Make sure the track begins where the visual timing expects it to.'],['Inspect key accents','Listen for beat hits that should line up with cuts or animation.'],['Check the ending','Avoid an unwanted abrupt cutoff when the clip ends.'],['Play the exported file','Confirm audio survived export and stays synchronized throughout.']],tip:'Use headphones or a quiet environment for final review, and avoid boosting levels blindly if the source already clips.',challenge:'Review a short edit once with the waveform or timeline, then once with your eyes away from the screen to focus on sound.'},
{id:'visual-hierarchy',title:'One focal point per moment',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-spark',color:'#05faa8',desc:'Reduce competing elements so the viewer knows where to look.',intro:'Visual hierarchy is the order the viewer notices elements. Too many bright accents, moving titles and effects at once can flatten that order.',steps:[['Pick the hero element','Decide whether the subject, title or action is the focal point for this moment.'],['Lower competing accents','Reduce contrast, movement or scale on secondary elements.'],['Use timing to shift focus','Let one item lead, then hand attention to the next.'],['Review a small preview','The hierarchy should remain clear when the canvas is viewed at normal size.']],tip:'When everything glows and shakes, nothing feels like the main event.',challenge:'Create a frame with one focal title, one supporting accent and a restrained background.'},
{id:'remove-visual-clutter',title:'Clean visual clutter from a composition',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-layers',color:'#05faa8',desc:'Decide which layers deserve to stay in the final shot.',intro:'A polish pass should remove distractions as well as add detail. Repeated overlays and effects can obscure the subject without adding useful meaning.',steps:[['Duplicate or back up the project','Keep the original if you need to compare.'],['Toggle layers one by one','Hide overlays, glows and accents to see what each contributes.'],['Remove or reduce low-value layers','Keep effects that improve focus, depth, motion or readability.'],['Preview the result at full speed','Make sure the edit still has energy after removing clutter.']],tip:'If a layer is barely visible and has no structural purpose, question whether it needs to be there.',challenge:'Turn off three optional polish layers in a copy and decide which ones truly improve the frame.'},
{id:'micro-animations',title:'Use micro-animation sparingly',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Add small movement to keep a layout alive without stealing focus.',intro:'Micro-animation is subtle scale, position, opacity or rotation used to make a static design feel responsive. It should remain secondary to the main message.',steps:[['Choose one static element','Start with a title, icon or accent.'],['Use a small range','Keep movement modest enough that the layout does not wobble.'],['Add a relaxed hold','Let the viewer see the design between small movements.'],['Check the loop','If it repeats, verify that the final frame returns cleanly to the start.']],tip:'Small changes become distracting when several layers animate independently at once.',challenge:'Add a subtle looping scale or opacity movement to one decorative element, leaving the main title still.'},
{id:'effect-copy-paste',title:'Copy effects with a control check',category:'Effects & style',filter:'effects',level:'Intermediate',icon:'i-effect',color:'#ffbf7a',desc:'Reuse effect work while respecting differences between clips.',intro:'Copying an effect stack can save time, but settings that suit one shot may not suit another because brightness, color and scale differ.',steps:[['Copy from a clean reference','Choose a layer whose treatment works for a reason.'],['Apply to the target','Use the copy/paste effects workflow available in your version.'],['Check source differences','Compare exposure, subject size and background contrast.'],['Retune important settings','Adjust glow, blur, saturation and opacity as needed instead of keeping every value blindly.']],tip:'Consistency means a coherent result, not identical numbers on every shot.',challenge:'Apply the same simple effect stack to two different images and tune each for consistent perceived intensity.'},
{id:'slow-mo-vs-slow-move',title:'Slow-motion footage vs slow animation',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-timeline',color:'#82aaff',desc:'Distinguish retiming video from slowing down a keyframed move.',intro:'Slow-motion footage changes how source frames are played, while a slow animation changes the timing of keyframed properties. They are related but not the same technique.',steps:[['Identify what is slow','Decide whether the footage itself or an animated overlay is moving too quickly.'],['Retiming the source','Use the available speed/retiming feature for video if supported, and inspect frame cadence.'],['Retiming animation','Adjust keyframe spacing and easing to change how a property moves.'],['Review both together','Make sure the overlay motion still fits the retimed footage.']],tip:'Adding more frames or changing FPS alone does not create genuine new slow-motion detail from a limited source.',challenge:'Create a short title animation over a clip and separately adjust the title timing without changing the footage speed.'},
{id:'camera-shake-control',title:'Camera shake that stays readable',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Make impact movement short, controlled and tied to an event.',intro:'A camera-shake look can be built from brief position or rotation changes. If the amplitude or duration is too high, the viewer can lose the subject.',steps:[['Define the impact frame','Choose the exact moment the shake should emphasize.'],['Use a short burst','Keep the movement brief and make the start easy to identify.'],['Vary the return gently','A quick settle usually reads better than a long random wobble.'],['Check text and edges','Make sure the shake does not push important content off-screen.']],tip:'Use one strong shake on an important event instead of continuous movement across the whole sequence.',challenge:'Build one short shake around a single beat and keep the subject within a safe frame.'},
{id:'motion-curve-reading',title:'Read an easing curve in plain language',category:'Animation',filter:'animation',level:'Intermediate',icon:'i-curve',color:'#82aaff',desc:'Translate graph shape into how an object will feel in motion.',intro:'A curve represents progress across time. Its slope indicates how quickly the animated property is changing at different parts of the interval.',steps:[['Find the beginning and end','Identify the start value and final value the curve connects.'],['Look at the slope','A steeper section means more change over that interval; a flatter section means less.'],['Look for a smooth landing','A flatter curve near the end can make a movement settle more gently.'],['Test with a clear motion','Apply the curve to a simple slide so you can connect graph shape to the visual result.']],tip:'Do not choose a curve because it looks fancy. Choose the one that supports the action.',challenge:'Try a linear curve, a curve that eases out and a curve with a sharper middle on the same move.'},
{id:'source-footage-prep',title:'Prepare source footage before effects',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-video',color:'#05faa8',desc:'Choose useful clips and set up clean source material.',intro:'Good source material makes editing easier. Selecting the right segment and checking orientation, clarity and audio before stacking effects saves effort later.',steps:[['Find the usable action','Pick the portion with the clearest pose or motion and the least unwanted camera obstruction.'],['Trim to the point','Remove excess lead-in and tail content after you understand the full shot.'],['Check orientation and quality','Confirm the source is not accidentally stretched, cropped or too small for the canvas.'],['Build the timing first','Place the shot and align key actions before adding finishing effects.']],tip:'No effect can reliably restore detail or timing that is missing from the source.',challenge:'Prepare a three-second source segment and note what makes it useful before applying any effect.'},
{id:'layer-lock-visibility',title:'Use visibility and lock controls safely',category:'Basics',filter:'basics',level:'Beginner',icon:'i-layers',color:'#05faa8',desc:'Temporarily hide or protect layers while working.',intro:'Visibility and locking controls can prevent accidental changes while you focus on another part of a project.',steps:[['Hide for diagnosis','Temporarily disable optional overlays to identify what they contribute.'],['Lock stable layers','Protect a finished background or reference layer if your version offers locking.'],['Restore before export','Check that important layers are visible and no layer is accidentally hidden.'],['Keep the stack understandable','Use names that tell you whether a layer is reference-only, final artwork or an effect.']],tip:'Use visibility toggles to test an idea before deleting a layer. Restore any hidden layer that belongs in the final result.',challenge:'Lock or protect a finished background while editing a title, then verify visibility before previewing.'},
{id:'project-naming',title:'Name projects for easy recovery',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-package',color:'#05faa8',desc:'Use clear names that tell you what version a file contains.',intro:'Project names help you find the correct source when several drafts or exports exist. A consistent naming rule prevents editing an outdated version by mistake.',steps:[['Name by content','Include the edit subject or project name.'],['Add stage or date when helpful','Use labels such as Draft, Review or FinalCandidate rather than several files all named final.'],['Separate exports from editable projects','Make the rendered video and editable project easy to tell apart.'],['Keep a clean final location','Move only confirmed final candidates into your delivery folder.']],tip:'Avoid repeatedly overwriting the only working copy during experiments.',challenge:'Rename three practice versions using a clear project-stage convention.'},
{id:'audio-waveform',title:'Use waveform and listening together',category:'Workflow',filter:'workflow',level:'Intermediate',icon:'i-bolt',color:'#05faa8',desc:'Align visuals using the waveform but trust the sound too.',intro:'A waveform helps locate transients and musical peaks, while listening gives context about rhythm and phrasing. Neither alone tells the full story.',steps:[['Find a strong transient','Use the waveform to spot a kick, clap or accent.'],['Listen to the surrounding phrase','Check whether that transient actually feels like the best visual cue.'],['Place the action','Align the cut or keyframe to the chosen moment.'],['Recheck in playback','A marker can look aligned while the perceived movement still feels late or early.']],tip:'For music edits, phrase changes and pauses can matter more than every individual beat.',challenge:'Pick one waveform peak, align a title change, then adjust by a few frames while listening to choose the best timing.'},
{id:'clean-final-review',title:'A final review pass that catches mistakes',category:'Workflow',filter:'workflow',level:'Beginner',icon:'i-check',color:'#05faa8',desc:'Review a finished edit from beginning to end with a repeatable checklist.',intro:'The last pass should focus on mistakes rather than inventing new effects. A consistent review catches common issues that are easy to miss during editing.',steps:[['Watch without touching controls','Play the whole edit and note visible issues instead of fixing each one immediately.'],['Check beginning and ending','Look for accidental black frames, sudden audio cuts or leftover layers.'],['Check text and subject visibility','Inspect the busiest frame and every key transition.'],['Review the exported file','Confirm the saved video is the same version you approved.']],tip:'A fresh second watch often reveals more than another round of randomly adding polish.',challenge:'Run the export checklist on a completed short edit and fix only the real issues it reveals.'}
];

const iconMap={'i-home':'i-home','i-grid':'i-grid','i-bookmark':'i-bookmark','i-play':'i-play','i-pause':'i-pause','i-bolt':'i-bolt','i-keyframe':'i-keyframe','i-curve':'i-curve','i-layers':'i-layers','i-code':'i-code','i-video':'i-video','i-users':'i-users','i-spark':'i-spark','i-arrow':'i-arrow','i-check':'i-check','i-search':'i-search','i-menu':'i-menu','i-close':'i-close','i-shield':'i-shield','i-external':'i-external','i-vector':'i-vector','i-type':'i-type','i-mask':'i-mask','i-effect':'i-effect','i-download':'i-download','i-lightbulb':'i-lightbulb','i-package':'i-package','i-heart':'i-heart','i-message':'i-message','i-plus':'i-plus','i-timeline':'i-timeline'};
const challenges=[
{id:'challenge-velocity',icon:'i-bolt',label:'Motion challenge',title:'One clean velocity hit',desc:'Build a fast move, land on a readable pose, and keep the impact brief.',lesson:'velocity'},
{id:'challenge-type',icon:'i-type',label:'Typography challenge',title:'Two-word entrance',desc:'Animate two words in sequence while keeping the message readable.',lesson:'text-kinetics'},
{id:'challenge-color',icon:'i-effect',label:'Effects challenge',title:'Glow with restraint',desc:'Create a clear halo while protecting crisp edges and contrast.',lesson:'glow-stack'},
{id:'challenge-loop',icon:'i-curve',label:'Animation challenge',title:'Seamless loop',desc:'Make a motion that returns to its first pose without a visible jump.',lesson:'looping-animation'},
{id:'challenge-vector',icon:'i-vector',label:'Design challenge',title:'Draw a tiny icon',desc:'Use a small number of vector points to make a clean shape.',lesson:'vector-drawing'},
{id:'challenge-project',icon:'i-package',label:'Workflow challenge',title:'Back up before experimenting',desc:'Create a safe checkpoint and note where the backup can be found.',lesson:'backup-projects'}
];
const popularIds=['getting-started','keyframes','easing-curves','null-objects','vector-drawing','xml-vs-package'];
const filterNames={all:'Everything',basics:'Basics',animation:'Animation',effects:'Effects & style',advanced:'Advanced',xml:'XML & files',vectors:'Vectors & text',workflow:'Workflow'};
const safeLoad=(key,fallback)=>{try{const v=localStorage.getItem(key);return v===null?fallback:JSON.parse(v)}catch(e){return fallback}};
const state={page:'home',filter:'all',query:'',current:null,saved:new Set(safeLoad('amcl_saved',[])),completed:new Set(safeLoad('amcl_completed',[])),challengeDone:new Set(safeLoad('amcl_challenges',[])),ideas:safeLoad('amcl_ideas',[]),notes:safeLoad('amcl_notes',{})};
const $=id=>document.getElementById(id);
function icon(name){return `<svg aria-hidden="true"><use href="#${iconMap[name]||name}"></use></svg>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function persist(){try{localStorage.setItem('amcl_saved',JSON.stringify([...state.saved]));localStorage.setItem('amcl_completed',JSON.stringify([...state.completed]));localStorage.setItem('amcl_challenges',JSON.stringify([...state.challengeDone]));localStorage.setItem('amcl_ideas',JSON.stringify(state.ideas));localStorage.setItem('amcl_notes',JSON.stringify(state.notes))}catch(e){toast('Browser storage is unavailable; progress may not persist.')}updateProgress()}
function updateProgress(){const done=state.completed.size,total=lessons.length,pct=Math.round(done/total*100);if(typeof refreshContinuePanel==='function')refreshContinuePanel();$('completedNumber').textContent=done;$('completedTotal').textContent=total;$('savedNumber').textContent=state.saved.size;$('savedCount').textContent=state.saved.size;$('lessonCount').textContent=total;$('homeProgressBar').style.width=pct+'%';$('sideProgressBar').style.width=pct+'%';$('sideProgressText').textContent=pct+'%';$('progressLabel').textContent=done===0?'Your learning journey starts now.':done===total?'Every tutorial marked learned. Keep experimenting!':`${total-done} lessons left to explore.`;$('sideProgressNote').textContent=done===0?'Pick one lesson to begin.':`${done} of ${total} lessons marked learned.`}
function cardTemplate(l){const saved=state.saved.has(l.id),done=state.completed.has(l.id);const lev=l.level==='Beginner'?'#05faa8':l.level==='Intermediate'?'#82aaff':'#c4a1ff';return `<article class="lesson-card" style="--iconcolor:${l.color};--iconbg:${l.color}17;--iconborder:${l.color}2c;--glow:${l.color}18;--badge:${lev}"><div class="lesson-card-top"><span class="lesson-ico" style="--iconcolor:${l.color};--iconbg:${l.color}16;--iconborder:${l.color}24">${icon(l.icon)}</span><button class="bookmark ${saved?'saved':''}" type="button" data-save="${l.id}" aria-label="${saved?'Remove saved lesson':'Save lesson'}" title="${saved?'Saved':'Save for later'}">${icon('i-bookmark')}</button></div><button class="lesson-open" type="button" data-open="${l.id}"><h3>${esc(l.title)} ${done?'<span class="card-check">✓</span>':''}</h3><p>${esc(l.desc)}</p><span class="lesson-footer"><span class="badge">${esc(l.level)}</span><span>${done?'Learned ✓':'Open walkthrough'} ${icon('i-arrow')}</span></span></button></article>`}
function renderGrid(id,list,emptyMessage){const el=$(id);if(!el)return;if(!list.length){el.innerHTML=`<div class="empty-state">${icon('i-search')}<strong>${esc(emptyMessage||'No lessons found')}</strong><span>Try another keyword or topic filter.</span></div>`;return}el.innerHTML=list.map(cardTemplate).join('')}
function visibleLessons(){let list=lessons.filter(l=>state.page!=='saved'||state.saved.has(l.id));if(state.filter!=='all')list=list.filter(l=>l.filter===state.filter);if(state.query){const q=state.query.toLowerCase();list=list.filter(l=>[l.title,l.category,l.desc,l.level,l.intro,l.tip,l.challenge].join(' ').toLowerCase().includes(q))}return list}
function render(){const list=visibleLessons();if(state.page==='home'){const featured=state.query?list.slice(0,6):popularIds.map(id=>lessons.find(l=>l.id===id)).filter(Boolean);renderGrid('homeGrid',featured,'No featured tutorials match. Open the library for more results.')}if(state.page==='tutorials')renderGrid('libraryGrid',list,'No tutorials match that search.');if(state.page==='saved')renderGrid('savedGrid',list,'No saved lessons yet. Tap the bookmark on any lesson to keep it here.');updateProgress();syncFilterPills();renderChallenges();renderIdeas()}
function syncFilterPills(){document.querySelectorAll('#tutorialFilters [data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===state.filter))}
function closeMobile(){ $('sidebar').classList.remove('open');$('mobileOverlay').classList.remove('show') }
function setPage(page){state.page=page;document.querySelectorAll('.page-view').forEach(el=>el.classList.toggle('active',el.id===`${page}Page`));document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('crumbCurrent').textContent=({home:'Home',tutorials:'Tutorial library',videos:'Video guides',community:'Community lab',playground:'Animation playground',tools:'Creator toolbench',saved:'Saved lessons'})[page]||'Home';closeMobile();render();window.scrollTo({top:0,behavior:'smooth'})}
function setFilter(filter){state.filter=filter;state.page='tutorials';setPage('tutorials')}
function toggleSave(id){if(state.saved.has(id)){state.saved.delete(id);toast('Removed from saved lessons')}else{state.saved.add(id);toast('Lesson saved to your shelf')}persist();render();if(state.current===id)updateModalButtons()}
function openLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;state.current=id;try{localStorage.setItem('amcl_last_opened',id)}catch(e){};const ni=$('lessonNoteInput');if(ni)ni.value=String(state.notes[id]||'');const ns=$('lessonNoteStatus');if(ns)ns.textContent=state.notes[id]?'Saved note loaded from this browser.':'No note saved yet.';refreshContinuePanel();$('modalCategory').textContent=`${l.category.toUpperCase()}  •  ${l.level.toUpperCase()}`;$('modalTitle').textContent=l.title;$('modalIntro').textContent=l.intro;$('modalSteps').innerHTML=l.steps.map((s,i)=>`<div class="modal-step"><div class="modal-step-num">${String(i+1).padStart(2,'0')}</div><div><strong>${esc(s[0])}</strong><p>${esc(s[1])}</p></div></div>`).join('');$('modalChallenge').textContent=l.challenge||'Try applying the main idea in a small practice project.';$('modalTip').textContent=l.tip;let resource=$('modalResource');if(resource)resource.remove();if(l.resource){const a=document.createElement('a');a.id='modalResource';a.className='inline-link';a.href=l.resource;a.target='_blank';a.rel='noopener noreferrer';a.style.marginBottom='14px';a.innerHTML='Open official related resource '+icon('i-external');$('modalSteps').after(a)}updateModalButtons();$('modalBackdrop').classList.add('show');document.body.style.overflow='hidden';$('modalClose').focus()}
function updateModalButtons(){if(!state.current)return;const saved=state.saved.has(state.current),done=state.completed.has(state.current);$('modalSave').innerHTML=`${icon('i-bookmark')}${saved?'Saved for later':'Save lesson'}`;$('modalComplete').innerHTML=`${icon('i-check')}${done?'Learned ✓':'Mark learned'}`;$('modalComplete').style.opacity=done?'.83':'1'}
function closeModal(){saveCurrentLessonNote(true);$('modalBackdrop').classList.remove('show');document.body.style.overflow='';state.current=null}
function handleCardClick(e){const save=e.target.closest('[data-save]');if(save){e.stopPropagation();toggleSave(save.dataset.save);return}const open=e.target.closest('[data-open]');if(open)openLesson(open.dataset.open)}
function showIntro(){ $('welcomeScreen').style.display='grid';$('enterHubBtn').focus() }
function enterHub(){ $('welcomeScreen').style.display='none';try{localStorage.setItem('amcl_intro_seen','1')}catch(e){} }
function renderChallenges(){const el=$('challengeGrid');if(!el)return;el.innerHTML=challenges.map(c=>{const done=state.challengeDone.has(c.id);return `<article class="community-card"><div class="community-top"><span class="community-icon">${icon(c.icon)}</span><span class="community-label">${esc(c.label)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><div class="challenge-actions"><button class="btn btn-secondary" data-open-challenge="${c.lesson}">Learn steps</button><button class="btn ${done?'btn-secondary':'btn-primary'}" data-challenge="${c.id}">${done?icon('i-check'):icon('i-check')}${done?'Completed':'Mark complete'}</button></div></article>`}).join('')}
function renderIdeas(){const el=$('ideaList');if(!el)return;if(!state.ideas.length){el.innerHTML='<div style="color:#71839a;font-size:10px;margin-top:4px">Your saved ideas will appear here.</div>';return}el.innerHTML=state.ideas.slice().reverse().map((idea,i)=>`<div class="idea-item">${icon('i-lightbulb')}<div><strong style="display:block;color:#e1eaf4;margin-bottom:2px">${esc(idea.title)}</strong>${esc(idea.body)}</div><button data-delete-idea="${state.ideas.length-1-i}" aria-label="Delete idea" title="Delete idea" style="margin-left:auto;background:transparent;color:#8192a7;border:0;padding:0 0 0 7px">${icon('i-close')}</button></div>`).join('')}
function setMotionMode(mode){const stage=$('playgroundStage');stage.classList.remove('mode-smooth','mode-bounce','mode-linear');stage.classList.add('mode-'+mode);document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));const hint={smooth:'Smooth ease starts gently, speeds up, then settles. It is useful when you want motion to feel designed rather than mechanical.',bounce:'Bounce overshoots and returns. Use this for playful movement, but reduce the bounce when the subject should feel heavy or precise.',linear:'Linear movement changes at a constant rate. It can be useful for technical movement, but often looks mechanical for titles and character motion.'};$('motionHint').textContent=hint[mode]||hint.smooth}
function toggleDemo(){const stage=$('playgroundStage'),playing=stage.classList.toggle('playing');$('togglePlay').innerHTML=`${icon(playing?'i-pause':'i-play')}${playing?'Pause demo':'Play demo'}`}

$('enterHubBtn').addEventListener('click',enterHub);$('welcomeIntroBtn').addEventListener('click',()=>{enterHub();setPage('home');toast('Welcome! Use the navigation to explore each section.')});$('replayIntroBtn').addEventListener('click',showIntro);$('introTopBtn').addEventListener('click',showIntro);
document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));document.querySelectorAll('.path-link').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));document.querySelectorAll('#tutorialFilters [data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;render();}));document.querySelectorAll('[data-quick-filter]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.quickFilter)));
['homeGrid','libraryGrid','savedGrid'].forEach(id=>$(id).addEventListener('click',handleCardClick));$('searchInput').addEventListener('input',e=>{state.query=e.target.value.trim();if(state.query&&!['home','tutorials','saved'].includes(state.page)){setPage('tutorials');return}render()});$('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&state.query)setPage('tutorials')});
$('exploreBtn').addEventListener('click',()=>{state.filter='all';setPage('tutorials')});$('viewAllBtn').addEventListener('click',()=>{state.filter='all';setPage('tutorials')});$('startLearningBtn').addEventListener('click',()=>openLesson('getting-started'));$('goVideosBtn').addEventListener('click',()=>setPage('videos'));$('openWorkflowTip').addEventListener('click',()=>openLesson('layer-naming'));$('openEasingLesson').addEventListener('click',()=>openLesson('easing-curves'));
$('menuBtn').addEventListener('click',()=>{$('sidebar').classList.add('open');$('mobileOverlay').classList.add('show')});$('mobileOverlay').addEventListener('click',closeMobile);
$('modalClose').addEventListener('click',closeModal);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal()});$('modalSave').addEventListener('click',()=>{if(state.current)toggleSave(state.current)});$('modalComplete').addEventListener('click',()=>{if(!state.current)return;if(state.completed.has(state.current)){state.completed.delete(state.current);toast('Lesson marked not learned')}else{state.completed.add(state.current);toast('Lesson marked learned. Nice!')}persist();render();updateModalButtons()});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('modalBackdrop').classList.contains('show')){e.preventDefault();$('searchInput').focus()}if(e.key==='Escape'){closeModal();closeMobile();if($('welcomeScreen').style.display!=='none')enterHub()}});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMotionMode(b.dataset.mode)));$('togglePlay').addEventListener('click',toggleDemo);$('restartDemo').addEventListener('click',()=>{const stage=$('playgroundStage');stage.classList.remove('playing');void stage.offsetWidth;stage.classList.add('playing');$('togglePlay').innerHTML=`${icon('i-pause')}Pause demo`;toast('Preview replayed')});
$('challengeGrid').addEventListener('click',e=>{const open=e.target.closest('[data-open-challenge]');if(open){openLesson(open.dataset.openChallenge);return}const b=e.target.closest('[data-challenge]');if(!b)return;const id=b.dataset.challenge;if(state.challengeDone.has(id)){state.challengeDone.delete(id);toast('Challenge reopened')}else{state.challengeDone.add(id);toast('Challenge marked complete!')}persist();renderChallenges()});
$('ideaForm').addEventListener('submit',e=>{e.preventDefault();const title=$('ideaTitle').value.trim(),body=$('ideaBody').value.trim();if(!title||!body)return;state.ideas.push({title,body,created:Date.now()});$('ideaTitle').value='';$('ideaBody').value='';persist();renderIdeas();toast('Added to your local idea board')});$('ideaList').addEventListener('click',e=>{const b=e.target.closest('[data-delete-idea]');if(!b)return;state.ideas.splice(Number(b.dataset.deleteIdea),1);persist();renderIdeas();toast('Idea removed')});

// Creator Toolbench: all controls below perform real local calculations or browser-only previews.
const beatState = {text:''};
function clamp(n,min,max){return Math.min(max,Math.max(min,n))}
function fmtClock(seconds){const mins=Math.floor(seconds/60),secs=seconds-mins*60;return `${mins}:${secs.toFixed(3).padStart(6,'0')}`}
function updateFrameCalc(){const fps=clamp(Number($('calcFps').value)||30,1,240),dur=clamp(Number($('calcDuration').value)||0,0,3600),framesIn=clamp(Math.round(Number($('calcFrames').value)||0),0,1000000);const frames=Math.round(dur*fps);$('calcResultFrames').textContent=`${frames.toLocaleString()} frames`;$('calcResultTime').textContent=`${(frames/fps).toFixed(2)} seconds at ${fps} FPS`;if(document.activeElement===$('calcFrames')){$('calcResultFrames').textContent=`${framesIn.toLocaleString()} entered frames`;$('calcResultTime').textContent=`${(framesIn/fps).toFixed(3)} seconds at ${fps} FPS`;}}
function ratioValues(){const [w,h]=$('ratioPreset').value.split(':').map(Number);const width=clamp(Number($('ratioWidth').value)||1080,1,20000);const height=Math.round(width*h/w);$('ratioResult').textContent=`${width.toLocaleString()} × ${height.toLocaleString()} px`;$('ratioDecimal').textContent=`Width:height ${w}:${h} · decimal ratio ${(w/h).toFixed(4)}`;return `${width} × ${height} px (${w}:${h})`}
function generateBeatMarkers(){const bpm=clamp(Number($('beatBpm').value)||120,20,300),duration=clamp(Number($('beatDuration').value)||12,1,300),div=clamp(Number($('beatSubdivisions').value)||1,1,4);const interval=60/bpm/div;const count=Math.min(300,Math.floor(duration/interval)+1);const rows=[];for(let i=0;i<count;i++){const t=i*interval;if(t>duration+1e-8)break;rows.push({i,t})}beatState.text=`BPM: ${bpm}\nDuration: ${duration}s\nSubdivision: ${div} per beat\n\n`+rows.map(({i,t})=>`${String(i+1).padStart(3,'0')}  ${fmtClock(t)}  (${t.toFixed(3)} s)`).join('\n');$('beatOutput').innerHTML=`<small>${bpm} BPM · ${div===1?'quarter-note beats':div===2?'half-beat divisions':'quarter-beat divisions'} · showing ${rows.length} markers</small>`+rows.slice(0,80).map(({i,t})=>`<div class="beat-line"><span>Marker ${String(i+1).padStart(2,'0')}</span><span>${fmtClock(t)}</span></div>`).join('')+(rows.length>80?`<small>Preview limited to the first 80. Copy marker list includes all ${rows.length} markers.</small>`:'');$('copyBeatsBtn').disabled=!rows.length;}
function bezierValues(){return {x1:Number($('curveX1').value)/100,y1:Number($('curveY1').value)/100,x2:Number($('curveX2').value)/100,y2:Number($('curveY2').value)/100}}
function updateBezier(){const v=bezierValues(),p1x=v.x1*100,p1y=(1-v.y1)*100,p2x=v.x2*100,p2y=(1-v.y2)*100;$('curvePath').setAttribute('d',`M0 100 C${p1x} ${p1y} ${p2x} ${p2y} 100 0`);$('curveDot1').setAttribute('cx',p1x);$('curveDot1').setAttribute('cy',p1y);$('curveDot2').setAttribute('cx',p2x);$('curveDot2').setAttribute('cy',p2y);$('x1Val').textContent=v.x1.toFixed(2);$('y1Val').textContent=v.y1.toFixed(2);$('x2Val').textContent=v.x2.toFixed(2);$('y2Val').textContent=v.y2.toFixed(2);$('bezierCode').textContent=`cubic-bezier(${v.x1.toFixed(2)}, ${v.y1.toFixed(2)}, ${v.x2.toFixed(2)}, ${v.y2.toFixed(2)})`;const obj=$('curvePreviewObject');obj.style.transitionTimingFunction=`cubic-bezier(${v.x1}, ${v.y1}, ${v.x2}, ${v.y2})`;}
function playCurve(){const obj=$('curvePreviewObject');const v=bezierValues();obj.style.transition='none';obj.style.transform='translateX(0)';void obj.offsetWidth;obj.style.transition=`transform 900ms cubic-bezier(${v.x1}, ${v.y1}, ${v.x2}, ${v.y2})`;requestAnimationFrame(()=>{obj.style.transform='translateX(min(72vw, 510px))'});setTimeout(()=>{obj.style.transition='none';obj.style.transform='translateX(0)'},1100)}
const titleRecipes={clean:'Recipe: bold font, clear contrast, generous spacing and no unnecessary decoration.',glow:'Recipe: bright text, subtle glow, low enough intensity to preserve letter edges. Use the app’s glow effect and tune radius/opacity by eye.',outline:'Recipe: use an outline or stroke treatment, keep the inside transparent or contrasting, and avoid making the stroke heavier than the letter.',shadow:'Recipe: short offset, moderate softness and low-to-medium opacity. Check that the shadow separates rather than doubles the letters.',gradient:'Recipe: use a restrained two- or three-color gradient with enough contrast against the background; verify that every word remains readable.',impact:'Recipe: use a heavy typeface, strong contrast and one controlled offset/accent. Save the biggest treatment for the key word.'};
function updateTitlePreview(){const text=$('titlePreviewInput').value.trim()||'YOUR NEXT EDIT',style=$('titleStyleSelect').value;const el=$('titlePreviewText');el.textContent=text;el.className=`title-preview-text style-${style}`;$('titleRecipeText').textContent=titleRecipes[style]||titleRecipes.clean}
function hexRgb(hex){const h=hex.replace('#','');return {r:parseInt(h.slice(0,2),16),g:parseInt(h.slice(2,4),16),b:parseInt(h.slice(4,6),16)}}
function rgbHsl({r,g,b}){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b);let h=0,s=0,l=(max+min)/2;if(max!==min){const d=max-min;s=l>.5?d/(2-max-min):d/(max+min);switch(max){case r:h=(g-b)/d+(g<b?6:0);break;case g:h=(b-r)/d+2;break;case b:h=(r-g)/d+4;break}h/=6}return {h:h*360,s:s*100,l:l*100}}
function hslHex(h,s,l){h=((h%360)+360)%360;s=clamp(s,0,100)/100;l=clamp(l,0,100)/100;const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let rp=0,gp=0,bp=0;if(h<60){rp=c;gp=x}else if(h<120){rp=x;gp=c}else if(h<180){gp=c;bp=x}else if(h<240){gp=x;bp=c}else if(h<300){rp=x;bp=c}else{rp=c;bp=x}const to=v=>Math.round((v+m)*255).toString(16).padStart(2,'0');return '#'+to(rp)+to(gp)+to(bp)}
let currentPalette=[];
function updatePalette(){const base=rgbHsl(hexRgb($('paletteBase').value)),hues=[-34,-16,0,16,34],names=['Accent A','Accent B','Base','Accent C','Accent D'];currentPalette=hues.map((off,i)=>hslHex(base.h+off,clamp(base.s+(i===2?0:(i%2?7:-5)),18,95),clamp(base.l+(i===0?14:i===4?-13:i===1?7:i===3?-5:0),12,88)));$('paletteSwatches').innerHTML=currentPalette.map((c,i)=>`<button class="palette-swatch" data-palette-color="${c}" title="Copy ${c}"><span class="swatch-color" style="background:${c}"></span><small>${c.toUpperCase()}</small></button>`).join('');const mood=base.h<45||base.h>330?'Warm accent':base.h<155?'Mint spectrum':base.h<260?'Cool spectrum':'Violet spectrum';$('paletteMood').textContent=mood}
const exportChecks=safeLoad('amcl_export_checks',{});
function updateExportChecks(){let done=0;document.querySelectorAll('[data-export-check]').forEach(el=>{el.checked=!!exportChecks[el.dataset.exportCheck];if(el.checked)done++});$('exportCheckProgress').style.width=(done/6*100)+'%';$('exportCheckLabel').textContent=`${done} of 6 checked`;try{localStorage.setItem('amcl_export_checks',JSON.stringify(exportChecks))}catch(e){}}
const effectRecipes=[
{title:'Clean title glow',purpose:'Separate a title from a dark or medium background without washing out the edges.',tags:['Typography','Glow','Readability'],steps:['Start with a sharp, high-contrast title.','Add one glow effect supported by your version.','Increase intensity only until the letters gain separation.','Check the glow on the brightest frame and reduce it if letter shapes disappear.']},
{title:'Impact shake',purpose:'Emphasize one hit, cut or dramatic beat with a brief movement burst.',tags:['Impact','Keyframes','Timing'],steps:['Pick the exact impact frame.','Add a small position or rotation change around the hit.','Use a few closely spaced keyframes for a short burst, then return to the resting pose.','Preview at normal speed and keep the subject within the safe frame.']},
{title:'Soft zoom-in',purpose:'Guide attention toward a subject without creating a sudden jump.',tags:['Scale','Easing','Camera'],steps:['Create the start and end scale/position values.','Choose an interval long enough to read.','Apply a gentle ease-out so the movement settles.','Check the anchor point and edge crops before adding blur.']},
{title:'Chromatic accent',purpose:'Add a short RGB-split-style accent to a key moment, not every frame.',tags:['Color','Impact','Advanced'],steps:['Duplicate or offset color channels only if your workflow supports it.','Keep the split distance small enough for the subject to remain recognizable.','Restrict the accent to the impact interval using layer timing or masking.','Return to a clean frame after the accent.']},
{title:'Parallax depth',purpose:'Create a layered sense of depth from separated foreground and background elements.',tags:['Layers','Depth','Movement'],steps:['Separate foreground, subject and background where you have usable assets.','Move layers at slightly different rates or use a camera system if supported.','Keep the background movement smaller and slower than the foreground.','Check for empty edges or missing areas exposed by the movement.']},
{title:'Readable motion blur',purpose:'Support fast travel while leaving the final pose easy to see.',tags:['Blur','Velocity','Clarity'],steps:['Build the position movement first.','Apply a suitable motion blur or directional blur control available in your version.','Tune strength on the moving section, then inspect the final pose.','Remove blur if it hides the action more than it supports it.']}
];
function renderRecipes(){$('recipeList').innerHTML=effectRecipes.map((r,i)=>`<article class="recipe-card"><h4>${r.title}</h4><p>${r.purpose}</p><div class="recipe-tags">${r.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><button class="tool-mini-btn" data-copy-recipe="${i}">Copy steps</button></article>`).join('')}
const glossary=[
['Anchor / pivot','The point around which a layer rotates or scales. Its exact controls depend on the app and object type.'],['Aspect ratio','The relationship between canvas width and height, such as 9:16 or 16:9.'],['Beat marker','A note marking a musical event or timing point for editing. A beat planner does not write markers into the project.'],['Bezier curve','A curve controlled by points and handles. Cubic-bezier values can describe easing between two states.'],['Bitrate','The amount of data used per second of video or audio. It affects file size and can affect quality.'],['Blend mode','A rule for combining a layer’s colors with layers underneath.'],['Canvas','The composition frame visible in the project preview.'],['Chroma key','A technique that makes a selected color range transparent, often used for green-screen footage.'],['Codec','A method for encoding or decoding media, such as H.264 for video.'],['Compositing','Combining video, images, shapes, effects and other layers into one final image.'],['Curve / easing','Controls how progress changes between keyframes over time.'],['Export','Rendering a project into a video, image sequence or another output format.'],['FPS / frame rate','The number of frames shown or encoded per second. Higher FPS does not automatically fix poor timing.'],['Frame','One still image in a sequence of moving images.'],['Frame pacing','How evenly frames are presented over time during playback.'],['Glow','A light-like effect that spreads brightness around selected content.'],['Group','A collection of layers managed together for organization or transforms.'],['Keyframe','A recorded value for a property at a particular time.'],['Layer','A piece of media, text, shape, audio or other content in a composition.'],['Mask','A control that limits which parts of a layer remain visible.'],['Motion blur','A visual streak or softness associated with movement. Excessive blur can hide detail.'],['Null object','A controller layer that can drive other layers through parenting when supported.'],['Opacity','How transparent or visible a layer is.'],['Parent / child','A relationship where one layer follows a parent’s transforms in a hierarchy.'],['Parallax','A depth effect where different layers move at different rates.'],['Project package','An app-supported way of sharing an editable project structure, distinct from a rendered video.'],['QR transfer','A QR-based project-sharing flow where supported by the app. A code is not proof a file is compatible.'],['Raster image','An image made from pixels, such as a PNG or JPG.'],['Resolution','The pixel width and height of a canvas or exported video.'],['Retiming','Changing when media or an animation plays, including speed changes.'],['Safe zone','An area where important content is kept away from edges or interface overlays.'],['Staggering','Offsetting layer entrances or animations so they happen in sequence.'],['Stroke','The visible outline or line drawn along a shape or path.'],['Timeline','The area that organizes layers and events across time.'],['Vector path','A shape represented by points and curves rather than a fixed pixel grid.'],['Waveform','A visual representation of audio amplitude over time.'],['XML','A structured text format. An XML extension alone does not make a file an Alight Motion preset or project.'],['Velocity','How quickly a property changes over time. In editing, the term is often used for speed-focused movement.'],['Visual hierarchy','The order in which the viewer notices the most important elements.'],['Project backup','A separate copy intended to help recover or revise a project if something goes wrong.']
];
function renderGlossary(){const q=$('glossarySearch').value.trim().toLowerCase();const terms=glossary.filter(([term,def])=>!q||(term+' '+def).toLowerCase().includes(q));$('glossaryList').innerHTML=terms.length?terms.map(([term,def])=>`<article class="glossary-entry"><strong>${esc(term)}</strong><p>${esc(def)}</p></article>`).join(''):'<div class="xml-report"><strong>No matching terms</strong><p>Try a shorter word or another editing term.</p></div>'}
function buildProjectPlan(){const name=$('planName').value.trim()||'Untitled edit',type=$('planType').value,ratio=$('planRatio').value,fps=$('planFps').value,duration=clamp(Number($('planDuration').value)||15,1,600),mood=$('planMood').value;const frames=Math.round(duration*parseInt(fps));const plan=`ALIGHT MOTION PROJECT BLUEPRINT\n=============================\nProject: ${name}\nType: ${type}\nCanvas: ${ratio}\nFrame rate target: ${fps}\nTarget duration: ${duration} seconds (~${frames} frames)\nVisual mood: ${mood}\n\nBUILD ORDER\n1. Create the project with the target canvas and frame rate.\n2. Gather source media, fonts and audio; note any assets that need permission or replacement.\n3. Block the timeline with the main shots and audio timing.\n4. Animate core position, scale and opacity before adding complex effects.\n5. Tune easing and direction continuity.\n6. Add a restrained effect stack and color treatment.\n7. Review text readability, crop-safe zones and audio sync.\n8. Save a backup and export a representative short test.\n9. Watch the actual export, then render the full edit if the test passes.\n\nFINAL REVIEW\n[ ] Main subject readable\n[ ] Title inside safe zone\n[ ] Audio aligned\n[ ] Last frame intentional\n[ ] Editable project backup saved\n[ ] Export reviewed on target device\n\nNote: This is a planning document, not an Alight Motion project file.`;$('planOutput').textContent=plan;$('downloadPlanBtn').disabled=false;$('copyPlanBtn').disabled=false;return plan}
async function copyText(text,label='Copied'){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw new Error('copy failed')}toast(label)}catch(e){toast('Copy unavailable in this browser. You can select the text manually.')}}
function downloadText(filename,text,mime='text/plain'){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function inspectXmlFile(file){const out=$('xmlReport');if(!file){out.innerHTML='<strong>No file selected</strong><p>Choose an XML file to inspect.</p>';return}if(file.size>2*1024*1024){out.innerHTML='<strong>File too large for this quick check</strong><p>Choose a file under 2 MB. Nothing was uploaded.</p>';return}const validExt=/\.xml$/i.test(file.name)||/xml/i.test(file.type);if(!validExt){out.innerHTML='<strong>Please select an XML file</strong><p>This inspector only checks XML text files.</p>';return}file.text().then(text=>{const parser=new DOMParser();const doc=parser.parseFromString(text,'application/xml');const err=doc.querySelector('parsererror');if(err){out.innerHTML=`<strong style="color:#ffb5c5">XML syntax error detected</strong><p>File: ${esc(file.name)} · ${(file.size/1024).toFixed(1)} KB<br>The XML parser reported a syntax issue. This tool does not repair the file or determine app compatibility.</p>`;return}const root=doc.documentElement?doc.documentElement.nodeName:'(no root element)';const names=[...new Set([...doc.getElementsByTagName('*')].map(n=>n.nodeName))].slice(0,18);const counts=doc.getElementsByTagName('*').length;out.innerHTML=`<strong style="color:#a8ffdc">XML is well-formed ✓</strong><p>File: ${esc(file.name)} · ${(file.size/1024).toFixed(1)} KB<br>Root tag: ${esc(root)}<br>Element count: ${counts}<br>This confirms basic XML syntax only, not whether Alight Motion can import it.</p><div class="xml-chip-row">${names.map(n=>`<span class="xml-chip">${esc(n)}</span>`).join('')}${names.length===0?'<span class="xml-chip">No tags found</span>':''}</div>`}).catch(()=>{out.innerHTML='<strong>Could not read this file</strong><p>Try selecting the file again in your browser. The file was not uploaded.</p>'})}
function exportHubBackup(){const data={format:'am-community-lab-backup',version:2,exportedAt:new Date().toISOString(),saved:[...state.saved],completed:[...state.completed],challengeDone:[...state.challengeDone],ideas:state.ideas,notes:state.notes,lastOpened:safeLoad('amcl_last_opened','getting-started'),storyboard,reducedMotion:document.body.classList.contains('reduced-motion'),exportChecks};downloadText('am-community-lab-backup.json',JSON.stringify(data,null,2),'application/json');$('hubBackupStatus').innerHTML='<strong>Backup exported</strong><p>Your learning hub data has been downloaded as JSON. Store it somewhere safe if you want to restore it later.</p>'}
function importHubBackup(file){if(!file)return;if(file.size>1024*1024){toast('Backup file is too large');return}file.text().then(raw=>{const d=JSON.parse(raw);if(!d||d.format!=='am-community-lab-backup')throw new Error('wrong format');const lessonIds=new Set(lessons.map(l=>l.id)),challengeIds=new Set(challenges.map(c=>c.id));state.saved=new Set((Array.isArray(d.saved)?d.saved:[]).filter(x=>lessonIds.has(x)));state.completed=new Set((Array.isArray(d.completed)?d.completed:[]).filter(x=>lessonIds.has(x)));state.challengeDone=new Set((Array.isArray(d.challengeDone)?d.challengeDone:[]).filter(x=>challengeIds.has(x)));state.ideas=(Array.isArray(d.ideas)?d.ideas:[]).slice(-100).map(x=>({title:String(x.title||'Idea').slice(0,70),body:String(x.body||'').slice(0,240),created:Number(x.created)||Date.now()}));state.notes={};if(d.notes&&typeof d.notes==='object'&&!Array.isArray(d.notes)){Object.entries(d.notes).forEach(([k,v])=>{if(lessonIds.has(k)&&typeof v==='string'&&v.trim())state.notes[k]=v.slice(0,4000)})}try{localStorage.setItem('amcl_last_opened',lessonIds.has(d.lastOpened)?d.lastOpened:'getting-started')}catch(e){}storyboard=(Array.isArray(d.storyboard)?d.storyboard:[]).slice(0,40).map(x=>({title:String(x.title||'Scene').slice(0,55),duration:clamp(Number(x.duration)||2.5,.1,300),note:String(x.note||'').slice(0,120)}));saveStoryboard();setReducedMotion(d.reducedMotion===true);Object.keys(exportChecks).forEach(k=>delete exportChecks[k]);if(d.exportChecks&&typeof d.exportChecks==='object')Object.assign(exportChecks,d.exportChecks);persist();updateExportChecks();render();$('hubBackupStatus').innerHTML='<strong>Backup restored ✓</strong><p>Saved lessons, completions, challenges, idea-board posts, private notes, storyboard scenes, resume point and preferences were restored in this browser.</p>';toast('Hub backup restored')} ).catch(()=>{toast('That file is not a valid hub backup');$('hubBackupStatus').innerHTML='<strong>Backup not imported</strong><p>Choose a JSON backup exported by this hub. Your current data has not been replaced.</p>'})}


// Local-first additions in v4.
function localDayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function updateDailyStreak(){const today=localDayKey();try{const last=localStorage.getItem('amcl_last_active')||'';let streak=Math.max(0,Number(localStorage.getItem('amcl_active_streak'))||0);if(last!==today){const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);streak=last===localDayKey(yesterday)?streak+1:1;localStorage.setItem('amcl_last_active',today);localStorage.setItem('amcl_active_streak',String(streak))}$('streakCount').textContent=`${streak} active day${streak===1?'':'s'}`}catch(e){$('streakCount').textContent='Progress is local'}}
function refreshContinuePanel(){const fallback='getting-started';const id=safeLoad('amcl_last_opened',fallback);const l=lessons.find(x=>x.id===id)||lessons.find(x=>x.id===fallback);if(!l)return;$('continueTitle').textContent=l.title;$('continueDescription').textContent=state.completed.has(l.id)?'You marked this lesson learned. Review it, try a harder variation, or open another topic.':l.desc;$('continueLessonBtn').innerHTML=`${icon('i-arrow')}${state.completed.has(l.id)?'Review lesson':'Continue lesson'}`;$('continueLessonBtn').dataset.lessonId=l.id}
function saveCurrentLessonNote(silent=false){if(!state.current)return;const input=$('lessonNoteInput');if(!input)return;const value=input.value.trim().slice(0,4000);if(value)state.notes[state.current]=value;else delete state.notes[state.current];persist();const status=$('lessonNoteStatus');if(status)status.textContent=value?`Saved locally · ${value.length} characters`:'Note cleared. Nothing saved.';if(!silent)toast(value?'Lesson note saved on this device':'Lesson note cleared')}
function downloadCurrentLessonNote(){if(!state.current)return;const l=lessons.find(x=>x.id===state.current);const note=String($('lessonNoteInput').value||'').trim();if(!note){toast('Add a note before downloading it');return}downloadText(`${(l?.id||'lesson-note')}-notes.txt`,`${l?.title||'Lesson Notes'}\n${'='.repeat((l?.title||'Lesson Notes').length)}\n\n${note}\n\nSaved from AM Community Creator Studio.`, 'text/plain');toast('Lesson note downloaded')}
function setReducedMotion(value,save=true){document.body.classList.toggle('reduced-motion',!!value);const b=$('motionToggleBtn');if(b){b.setAttribute('aria-pressed',String(!!value));b.title=value?'Reduced motion is on':'Reduce interface animations'}if(save){try{localStorage.setItem('amcl_reduce_motion',value?'1':'0')}catch(e){}}}

let currentLayerStackText='';
function buildLayerStack(){const items=$('layerStackInput').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,50);if(!items.length){toast('Add at least one layer name');return}currentLayerStackText=`LAYER STACK PLAN (TOP TO BOTTOM)\n${'='.repeat(31)}\n`+items.map((name,i)=>`${String(i+1).padStart(2,'0')}. ${name}`).join('\n')+`\n\nPlanning note: verify actual stacking, masking and parenting inside the app.`;$('layerStackOutput').innerHTML=items.map((name,i)=>`<div class="stack-row"><small>Top ${String(i+1).padStart(2,'0')}</small><strong>${esc(name)}</strong></div>`).join('');$('copyLayerStackBtn').disabled=false;$('downloadLayerStackBtn').disabled=false;return currentLayerStackText}

let storyboard=safeLoad('amcl_storyboard',[]);if(!Array.isArray(storyboard))storyboard=[];
function saveStoryboard(){try{localStorage.setItem('amcl_storyboard',JSON.stringify(storyboard))}catch(e){toast('Could not save storyboard in this browser')}}
function storyboardText(){let t=0;const fps=clamp(Number($('calcFps')?.value)||30,1,240);const lines=storyboard.map((shot,i)=>{const start=t;const dur=clamp(Number(shot.duration)||1,.1,300);t+=dur;return `${String(i+1).padStart(2,'0')}. ${shot.title}\n   ${fmtClock(start)} → ${fmtClock(t)} · ${Math.round(dur*fps)} frames at ${fps} FPS\n   ${shot.note||'No note'}`});return `SCENE STORYBOARD\n================\nScenes: ${storyboard.length}\nTotal duration: ${t.toFixed(2)} seconds\nTimeline frame rate reference: ${fps} FPS\n\n${lines.join('\n\n')||'No scenes added yet.'}`}
function renderStoryboard(){let cursor=0;const fps=clamp(Number($('calcFps')?.value)||30,1,240);$('storyboardList').innerHTML=storyboard.length?storyboard.map((shot,i)=>{const start=cursor,duration=clamp(Number(shot.duration)||1,.1,300);cursor+=duration;return `<article class="story-shot"><div class="story-shot-head"><span class="story-shot-num">${String(i+1).padStart(2,'0')}</span><div class="story-shot-main"><strong>${esc(shot.title)}</strong><p>${esc(shot.note||'No action note added.')}<br>${fmtClock(start)} → ${fmtClock(cursor)} · ${Math.round(duration*fps)} frames</p></div><span class="story-shot-time">${duration.toFixed(1)}s</span></div><div class="story-shot-actions"><button data-shot-action="up" data-shot-index="${i}" ${i===0?'disabled':''}>↑ Move up</button><button data-shot-action="down" data-shot-index="${i}" ${i===storyboard.length-1?'disabled':''}>↓ Move down</button><button data-shot-action="delete" data-shot-index="${i}">Remove</button></div></article>`}).join(''):'<div class="xml-report"><strong>No scenes planned</strong><p>Add your first shot above. Each scene will receive a running timecode and frame estimate.</p></div>';$('storyboardSummary').textContent=`${storyboard.length} scene${storyboard.length===1?'':'s'} · ${cursor.toFixed(2)} seconds · ~${Math.round(cursor*fps)} frames at ${fps} FPS`}
function addStoryboardShot(){if(storyboard.length>=40){toast('Storyboard limit is 40 scenes');return}const title=$('storyShotTitle').value.trim()||`Scene ${storyboard.length+1}`,duration=clamp(Number($('storyShotDuration').value)||2.5,.1,300),note=$('storyShotNote').value.trim().slice(0,120);storyboard.push({title:title.slice(0,55),duration,note});saveStoryboard();renderStoryboard();$('storyShotTitle').value=`Scene ${storyboard.length+1}`;$('storyShotNote').value='';toast('Scene added to your local storyboard')}
function handleStoryboardAction(e){const b=e.target.closest('[data-shot-action]');if(!b)return;const i=Number(b.dataset.shotIndex),action=b.dataset.shotAction;if(!Number.isInteger(i)||i<0||i>=storyboard.length)return;if(action==='delete')storyboard.splice(i,1);else if(action==='up'&&i>0)[storyboard[i-1],storyboard[i]]=[storyboard[i],storyboard[i-1]];else if(action==='down'&&i<storyboard.length-1)[storyboard[i+1],storyboard[i]]=[storyboard[i],storyboard[i+1]];saveStoryboard();renderStoryboard()}
function linearizeChannel(n){n/=255;return n<=.04045?n/12.92:Math.pow((n+.055)/1.055,2.4)}
function relativeLuminance(hex){const {r,g,b}=hexRgb(hex);return .2126*linearizeChannel(r)+.7152*linearizeChannel(g)+.0722*linearizeChannel(b)}
function updateContrast(){const fg=$('contrastTextColor').value,bg=$('contrastBgColor').value,L1=relativeLuminance(fg),L2=relativeLuminance(bg),ratio=(Math.max(L1,L2)+.05)/(Math.min(L1,L2)+.05);$('contrastRatio').textContent=`${ratio.toFixed(2)}:1`;$('contrastVerdict').textContent=ratio>=7?'Excellent contrast':ratio>=4.5?'Good for normal text':ratio>=3?'Good for large text only':'Low contrast · adjust colors';$('contrastVerdict').style.color=ratio>=4.5?'#9fffd5':ratio>=3?'#ffd39d':'#ffb4c5';const normal=$('contrastNormalBadge'),large=$('contrastLargeBadge');normal.textContent=`Normal text (4.5:1): ${ratio>=4.5?'PASS':'CHECK'}`;large.textContent=`Large text (3:1): ${ratio>=3?'PASS':'CHECK'}`;normal.className=ratio>=4.5?'pass':'fail';large.className=ratio>=3?'pass':'fail'}
function updateSafeFrame(){const ratio=$('safeFrameRatio').value,inset=clamp(Number($('safeFrameInset').value)||10,0,30);$('safeFrameStage').style.aspectRatio=ratio.replace('/',' / ');$('safeFrameBox').style.inset=`${inset}%`;$('safeFrameCaption').textContent=`${ratio.replace('/',' : ')} canvas · ${inset}% inset on each edge. Use it as a guide, then verify the actual composition.`}
function updateFileSizeEstimate(){const duration=clamp(Number($('sizeDuration').value)||1,1,36000),video=clamp(Number($('sizeVideoBitrate').value)||.1,.1,500),audio=clamp(Number($('sizeAudioBitrate').value)||0,0,1536);const videoMB=video*duration/8,audioMB=audio*duration/8000,total=(videoMB+audioMB)*1.03;$('sizeEstimate').textContent=total>=1000?`${(total/1000).toFixed(2)} GB`:`${total.toFixed(1)} MB`;$('sizeEstimateDetail').textContent=`Video ~${videoMB.toFixed(1)} MB + audio ~${audioMB.toFixed(2)} MB + 3% container allowance.`}
let lastLadderText='';
function buildTimingLadder(){const fps=clamp(Number($('ladderFps').value)||60,1,240),bpm=clamp(Number($('ladderBpm').value)||120,20,300),sub=clamp(Number($('ladderSubdivision').value)||2,1,8),bars=clamp(Number($('ladderBars').value)||2,1,4),interval=60/bpm/sub,total=bars*4*sub;const rows=[];for(let i=0;i<=total&&i<=128;i++){const seconds=i*interval,frame=Math.round(seconds*fps),bar=Math.min(bars,Math.floor(Math.max(0,i-1)/(4*sub))+1),label=i===0?'START':`B${Math.floor(i/(4*sub))+1} · ${i%(4*sub)===0?'BAR':`beat ${Math.floor((i%(4*sub))/sub)+1}.${i%sub}`}`;rows.push(`${String(i+1).padStart(3,'0')}  ${fmtClock(seconds)}  frame ${String(frame).padStart(5,'0')}  ${label}`)}lastLadderText=`KEYFRAME TIMING LADDER\nFPS: ${fps} · BPM: ${bpm} · markers per beat: ${sub} · bars: ${bars}\nFrames between markers ≈ ${(fps*60/bpm/sub).toFixed(2)}\n\n${rows.join('\n')}\n\nFrame positions are rounded to whole frames; verify against the actual audio.`;$('ladderOutput').textContent=lastLadderText;$('copyLadderBtn').disabled=false;$('downloadLadderBtn').disabled=false}

