$('recipeList').addEventListener('click',e=>{const b=e.target.closest('[data-copy-recipe]');if(!b)return;const r=effectRecipes[Number(b.dataset.copyRecipe)];copyText(`${r.title}\nPurpose: ${r.purpose}\n\n${r.steps.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\nExact controls vary by app version; tune by eye.`,'Recipe steps copied')});$('glossarySearch').addEventListener('input',renderGlossary);
