$('contrastTextColor').addEventListener('input',updateContrast);$('contrastBgColor').addEventListener('input',updateContrast);$('safeFrameRatio').addEventListener('change',updateSafeFrame);$('safeFrameInset').addEventListener('change',updateSafeFrame);
['sizeDuration','sizeVideoBitrate','sizeAudioBitrate'].forEach(id=>$(id).addEventListener('input',updateFileSizeEstimate));$('buildLadderBtn').addEventListener('click',buildTimingLadder);$('copyLadderBtn').addEventListener('click',()=>lastLadderText&&copyText(lastLadderText,'Timing ladder copied'));$('downloadLadderBtn').addEventListener('click',()=>lastLadderText&&downloadText('am-keyframe-timing-ladder.txt',lastLadderText));
